/* data_movements.js — art movements as the market reads them (v22, 2 Nov 2026).
   One record per movement: dates (a negative year is BC; to: null means it runs to now), place, what it was, why it happened,
   how to look, artists, works {t, a, y, where}, the market today {state: heating | steady | cooling | thin, note, record, recordSrc},
   links (related movement ids), sources [label, url] and vf (V: every price in it checked against an opened page; S: secondary).
   Read by move.js (the Movements view and dossiers) and ask.js (the analyst’s index). Researched 2 Nov 2026. */
const MOVEMENTS=[
{id:'prehistoric',n:'Prehistoric cave and rock art',from:-43000,to:-3000,place:'Worldwide; Franco-Cantabrian caves',what:'Paintings, engravings and hand stencils made on cave walls and rock shelters by hunter-gatherers, from at least 45,000 years ago in Sulawesi and from about 36,000 years ago in the caves of France and Spain, among them Chauvet, Lascaux and Altamira. Animals dominate, drawn in charcoal, ochre and manganese by lamplight, often using the bulges of the rock to give them volume.',why:'It is the earliest surviving evidence of image-making and symbolic thought. Shading, overlapping and implied movement already appear at Chauvet, so skill was present from the start rather than the end of a slow evolution.',look:'Animals in profile with horns and hooves twisted toward the viewer, outlines that follow the rock’s contours, hand stencils blown in pigment, and images superimposed over millennia.',artists:['Aurignacian painters (Chauvet)','Gravettian painters (Pech Merle, Cosquer)','Magdalenian painters (Lascaux, Altamira)','Sulawesi painters (Leang Tedongnge)','San painters (southern Africa)','Aboriginal Australian rock artists (Murujuga, Arnhem Land)'],works:[{t:'Panel of the Horses',a:'Aurignacian painters',y:'c. 34,000 BCE',where:'Chauvet-Pont-d’Arc Cave, Ardèche (in situ; replica at Grotte Chauvet 2)'},{t:'Hall of the Bulls',a:'Magdalenian painters',y:'c. 15,000 BCE',where:'Lascaux Cave, Dordogne (in situ, closed; replica at Lascaux IV)'},{t:'Polychrome ceiling (bison)',a:'Magdalenian painters',y:'c. 14,000 BCE',where:'Altamira Cave, Cantabria (in situ; replica at the Museo de Altamira)'}],market:{state:'thin',note:'Cave and rock art is immovable and protected by the state, so it never trades; the market is in portable prehistoric objects, such as flint tools, Neolithic axes and Chalcolithic idols, offered in the antiquities sales of Christie’s, Sotheby’s and Bonhams in London and New York. Title risk dominates: the Chalcolithic ’Guennol Stargazer’ idol made $14.5m at Christie’s New York in April 2017, but the buyer cancelled after Turkey sued, and the statue returned to its consignor when Turkey lost on appeal in 2023.'},links:['egypt','greekroman'],sources:[['Met Heilbrunn Timeline: Chauvet Cave (ca. 30,000 B.C.)','https://www.metmuseum.org/toah/hd/chav/hd_chav.htm'],['Met Heilbrunn Timeline: Lascaux (ca. 15,000 B.C.)','https://www.metmuseum.org/toah/hd/lasc/hd_lasc.htm'],['Cultural Property News: Turkey loses Guennol Stargazer case (2023)','https://culturalpropertynews.org/turkey-loses-guennol-stargazer-case-statue-will-return-to-christies-and-steinhardt/']],vf:'V'},
{id:'egypt',n:'Ancient Egyptian art',from:-3100,to:-30,place:'Nile Valley, Egypt',what:'The art of the Nile Valley from the unification of Egypt around 3100 BCE to the Roman conquest in 30 BCE, made for tombs and temples rather than for display. Its purpose was to make the king, the gods and the dead present for eternity, so a strict canon of proportion held for almost three thousand years.',why:'It set the first lasting canon of the human figure and a monumental stone sculpture that Archaic Greek sculptors adopted. Akhenaten’s short-lived Amarna style, around 1350 BCE, shows that the canon was a choice, not a limit.',look:'Composite views with head and legs in profile but eye and shoulders frontal, hierarchic scale, grid-based proportions, hard stones such as granite and diorite, and hieroglyphs naming the owner.',artists:['Thutmose (sculptor at Amarna)','Bak (chief sculptor of Akhenaten)','Imhotep (architect of Djoser)','Senenmut (architect of Hatshepsut)','Irtysen (Middle Kingdom sculptor)','Deir el-Medina workshops (royal tomb painters)'],works:[{t:'King Menkaure and Queen (pair statue)',a:'Royal workshop',y:'c. 2490–2472 BCE',where:'Museum of Fine Arts, Boston'},{t:'The Seated Scribe',a:'Unknown',y:'c. 2600–2350 BCE',where:'Musée du Louvre, Paris'},{t:'Bust of Nefertiti',a:'Thutmose (workshop)',y:'c. 1345 BCE',where:'Neues Museum, Berlin'}],market:{state:'thin',note:'Egyptian antiquities sell in the antiquities sales of Christie’s, Sotheby’s and Bonhams in London and New York, where provenance documented before the 1970 UNESCO Convention now decides whether a piece can be sold at all. Museum-grade sculpture rarely surfaces; the record is the Old Kingdom statue of Sekhemka, sold by Northampton Museum for £15.76m (about $27m) at Christie’s London in 2014, a deaccession that cost the museum its accreditation.',record:'Unknown (Old Kingdom, 5th Dynasty), Statue of Sekhemka, c. 2400 BCE: $27m, Christie’s, London, 10 Jul 2014',recordSrc:'https://artfixdaily.com/news_feed/2014/07/13/6640-27-million-sale-of-egyptian-statue-stirs-controversy'},links:['prehistoric','greekroman','byzantine'],sources:[['Britannica: Egyptian art and architecture','https://www.britannica.com/art/Egyptian-art'],['The Saleroom: Northampton’s Egyptian statue sets record amid protest (2014)','https://content.the-saleroom.com/news/2014/northamptons-egyptian-statue-sets-14m-record-amid-saleroom-protest/'],['Artfix Daily: $27 million sale of Egyptian statue stirs controversy (2014)','https://artfixdaily.com/news_feed/2014/07/13/6640-27-million-sale-of-egyptian-statue-stirs-controversy']],vf:'V'},
{id:'greekroman',n:'Greek and Roman antiquity',from:-800,to:400,place:'Greece, Italy and the Mediterranean',what:'The art of the Greek city-states from the Geometric period around 800 BCE to the Hellenistic kingdoms, and of Rome, which absorbed, copied and adapted it until late antiquity. Its core idea was the idealised human body in proportion and movement, framed by an architecture of columns and orders.',why:'Greek sculptors moved from the rigid kouros to the relaxed contrapposto of the Classical period in about a century, and Rome turned that legacy into an imperial language of portraiture, relief and copies. Every later classical revival, from the Renaissance to Neoclassicism, starts here.',look:'Marble or bronze figures in contrapposto, drapery that reveals the body, black- or red-figure painted vases, and Roman portrait busts with unflattering detail; check marbles for later restoration and recutting.',artists:['Praxiteles (Roman copies after)','Lysippos','Polykleitos','Phidias','Exekias','Euphronios'],works:[{t:'Parthenon sculptures',a:'Phidias and workshop',y:'447–432 BCE',where:'British Museum, London, and Acropolis Museum, Athens'},{t:'Doryphoros (Spear-Bearer), Roman copy',a:'after Polykleitos',y:'original c. 440 BCE',where:'Museo Archeologico Nazionale, Naples'},{t:'Augustus of Prima Porta',a:'Unknown',y:'early 1st century CE',where:'Vatican Museums, Rome'}],market:{state:'steady',note:'Greek and Roman marbles, bronzes and vases sell in the antiquities sales of Christie’s, Sotheby’s and Bonhams in London and New York, but documented pre-1970 provenance is now essential and seizures by the Manhattan District Attorney are a live risk. Masterpieces are rare: the Roman bronze Artemis and the Stag made $28.6m at Sotheby’s New York in 2007, more than double the previous antiquities record of $11.6m, set by a Roman marble Venus at Christie’s London in 2002.',record:'Unknown (Roman, after a Greek model), Artemis and the Stag, bronze, 1st century BCE–1st century CE: $28.6m, Sotheby’s, New York, 7 Jun 2007',recordSrc:'https://copper.org/consumers/arts/2007/june/Sotheby_auction.php'},links:['egypt','byzantine','highren','neoclassicism'],sources:[['Met Heilbrunn Timeline: Roman Copies of Greek Statues','https://www.metmuseum.org/toah/hd/rogr/hd_rogr.htm'],['Copper Development Association: Sotheby’s sets record with Artemis and the Stag (2007)','https://copper.org/consumers/arts/2007/june/Sotheby_auction.php'],['Deseret News (AP): Bronze Artemis sells for $28.6 million, sets records (2007)','https://www.deseret.com/2007/6/9/20023258/bronze-artemis-sells-for-28-6-million-sets-records/']],vf:'V'},
{id:'byzantine',n:'Byzantine art and icons',from:330,to:1700,place:'Constantinople, the Balkans, Crete and Russia',what:'The Christian art of the Eastern Roman Empire from the founding of Constantinople in 330 to its fall in 1453, continued in Crete, the Balkans and Russia, where Andrei Rublev and Dionisy shaped the Moscow school. Its core idea is the icon: a consecrated image through which the holy person is present and venerated, not merely depicted.',why:'Iconoclasm (726–843) forced a theology of images that fixed types and compositions for a thousand years. Rublev’s lighter, rhythmic version of the Byzantine model became the measure of Russian art, and the cleaning of old icons in the early 1900s made them a source for the Russian avant-garde.',look:'Egg tempera on gessoed wooden panels with gold grounds, inverse perspective, elongated figures, fixed types such as the Hodegetria and the Pantokrator, and inscriptions; check for later overpainting and metal covers (oklads).',artists:['Emmanuel Tzanes','Angelos Akotantos','Simon Ushakov','Dionisy','Theophanes the Greek','Andrei Rublev'],works:[{t:'Christ Pantokrator',a:'Unknown (probably Constantinople)',y:'6th century',where:'Saint Catherine’s Monastery, Sinai'},{t:'Virgin of Vladimir',a:'Unknown (Constantinople)',y:'c. 1130',where:'State Tretyakov Gallery, Moscow'},{t:'Trinity',a:'Andrei Rublev',y:'c. 1411 or 1425–27',where:'Russian Orthodox Church (transferred from the State Tretyakov Gallery in 2023)'}],market:{state:'thin',note:'Icons sell mainly at specialist houses such as Jackson’s in Iowa and Bruun Rasmussen in Copenhagen and in Greek and Russian sales in London, with Cretan post-Byzantine panels and Russian icons of the 16th to 19th centuries making up most of the supply; sanctions since 2022 have removed much Russian buying. The house-claimed record for a Russian icon is a 16th-century Novgorod Descent from the Cross sold by Bruun Rasmussen in 2017 for €806,000 with premium, about twice the previous benchmark of $411,000 set at Christie’s New York in 1995.',record:'Novgorod School (anonymous), Descent from the Cross, 16th century: c.$0.9m (€806,000), Bruun Rasmussen, Copenhagen, 9 Jun 2017',recordSrc:'https://mynewsdesk.com/bruun-rasmussen-auctioneers/pressreleases/iconic-russian-auction-hammer-price-of-dkk-27-punktum-6-million-eu-3-punktum-7-million-2012868'},links:['greekroman','gothic','miriskusstva','russianavantgarde'],sources:[['Met Heilbrunn Timeline: Byzantium (ca. 330–1453)','https://www.metmuseum.org/toah/hd/byza/hd_byza.htm'],['Met Heilbrunn Timeline: Icons and Iconoclasm in Byzantium','https://www.metmuseum.org/toah/hd/icon/hd_icon.htm'],['Bruun Rasmussen press release: Russian icon sale and record (2017)','https://mynewsdesk.com/bruun-rasmussen-auctioneers/pressreleases/iconic-russian-auction-hammer-price-of-dkk-27-punktum-6-million-eu-3-punktum-7-million-2012868']],vf:'V'},
{id:'gothic',n:'Gothic and International Gothic painting',from:1250,to:1430,place:'Italy, France, Bohemia and Burgundy',what:'Painting on gold-ground wooden panels for altarpieces and private devotion, from Cimabue and Duccio in Tuscany in the later 13th century to the courtly International Gothic of around 1400 in Paris, Prague, Milan and Burgundy. Its core idea moved from the Byzantine icon toward narrative, emotion and, at court, refined luxury.',why:'Giotto and Duccio gave figures weight, space and feeling and prepared the Renaissance. International Gothic created a shared court style of elegant line, rich colour and closely observed detail that fed directly into early Netherlandish painting.',look:'Egg tempera on poplar or oak panel, tooled and punched gold leaf, ultramarine and vermilion, swaying figures in sinuous drapery, and pinnacled frames; original frames and unrestored gold add value.',artists:['Cimabue','Duccio di Buoninsegna','Giotto di Bondone','Simone Martini','Lorenzo Monaco','Gentile da Fabriano','Limbourg brothers'],works:[{t:'Maestà',a:'Duccio di Buoninsegna',y:'1308–11',where:'Museo dell’Opera del Duomo, Siena'},{t:'Annunciation with Saints Ansanus and Margaret',a:'Simone Martini and Lippo Memmi',y:'1333',where:'Uffizi Galleries, Florence'},{t:'Adoration of the Magi (Strozzi Altarpiece)',a:'Gentile da Fabriano',y:'1423',where:'Uffizi Galleries, Florence'}],market:{state:'thin',note:'Gold-ground panels trade in the Old Master sales of Christie’s and Sotheby’s in London and New York and at French regional houses, but intact works by major names are extremely rare, and panels cut from dismembered altarpieces make up most of the supply. Old Master auction sales rose 30% in 2025, and the benchmark remains Cimabue’s Christ Mocked, found in a kitchen in Compiègne and sold for €24.2m ($26.8m) at Actéon in Senlis in 2019, then the highest price for any pre-1500 Old Master.',record:'Cimabue, Christ Mocked, c. 1280: $26.8m, Actéon, Senlis, 27 Oct 2019',recordSrc:'https://news.artnet.com/market/cimabue-27-million-1690672'},links:['byzantine','earlyren','northernren'],sources:[['Britannica: Gothic art','https://www.britannica.com/art/Gothic-art'],['Artnet News: Lost Cimabue sells for $26.8 million (2019)','https://news.artnet.com/market/cimabue-27-million-1690672'],['Artlyst: Art Basel and UBS Art Market Report 2026 (2025 figures)','https://artlyst.com/art-basel-ubs-global-art-market-2026-reports-59-6-billion-recovery/']],vf:'V'},
{id:'earlyren',n:'Early Italian Renaissance',from:1400,to:1490,place:'Florence and central Italy',what:'The art of Florence and the courts of central and northern Italy from about 1400 to 1490, when architects, sculptors and painters revived classical forms and studied nature and anatomy. Its core idea was a rational, measurable world: linear perspective, solid bodies in real space and the dignity of the individual.',why:'Brunelleschi’s perspective, Masaccio’s weighty figures and Donatello’s sculpture made pictures read as windows onto real space. Medici and church patronage turned artists into celebrated intellectuals and set the pattern for the High Renaissance.',look:'Tempera and, from the 1470s, oil on panel, vanishing-point perspective, classical architecture, light from a single source, profile and three-quarter portraits, and gold used sparingly.',artists:['Sandro Botticelli','Fra Angelico','Filippo Lippi','Andrea Mantegna','Piero della Francesca','Masaccio','Donatello'],works:[{t:'Holy Trinity',a:'Masaccio',y:'c. 1427',where:'Santa Maria Novella, Florence'},{t:'The Flagellation of Christ',a:'Piero della Francesca',y:'c. 1460',where:'Galleria Nazionale delle Marche, Urbino'},{t:'The Birth of Venus',a:'Sandro Botticelli',y:'c. 1484–86',where:'Uffizi Galleries, Florence'}],market:{state:'thin',note:'Early Renaissance panels appear in the January Old Master sales in New York and the July and December sales in London, but autograph works by the major names surface only a few times a decade, so workshop pictures, cassone panels and drawings make up most of the supply. Botticelli’s Young Man Holding a Roundel made $92.2m at Sotheby’s New York in January 2021, nine times his previous record of $10.4m.',record:'Sandro Botticelli, Young Man Holding a Roundel, c. 1480: $92.2m, Sotheby’s, New York, 28 Jan 2021',recordSrc:'https://www.sothebys.com/en/press/newsflash-sandro-botticelli'},links:['gothic','highren','northernren','mannerism'],sources:[['Britannica: Renaissance art','https://www.britannica.com/art/Renaissance-art'],['Sotheby’s press release: Botticelli’s Young Man Holding a Roundel (2021)','https://www.sothebys.com/en/press/newsflash-sandro-botticelli']],vf:'V'},
{id:'northernren',n:'Northern Renaissance',from:1420,to:1580,place:'Flanders, the Netherlands and Germany',what:'Painting in Flanders, the Netherlands and the German lands from Jan van Eyck in the 1430s to Pieter Bruegel the Elder in the 1560s, with Dürer, Cranach and Holbein in Germany. Its core idea was the faithful rendering of the visible world, down to reflections and textures, first for devotion and then for portraiture, landscape and the open market.',why:'Flemish mastery of oil glazes changed European painting and was taken up in Italy by Antonello da Messina and the Venetians. Bruges and Antwerp created the first open art market, where panels were sold ready-made at fairs and in dedicated sales halls.',look:'Oil on oak panel built up in translucent glazes, minute detail of fabrics, metals and distant landscapes, symbolic objects in domestic interiors, and panels that can be dated by dendrochronology.',artists:['Pieter Brueghel the Younger','Lucas Cranach the Elder','Hans Memling','Jan Gossaert','Albrecht Dürer','Rogier van der Weyden','Jan van Eyck'],works:[{t:'Ghent Altarpiece (Adoration of the Mystic Lamb)',a:'Hubert and Jan van Eyck',y:'1432',where:'St Bavo’s Cathedral, Ghent'},{t:'The Descent from the Cross',a:'Rogier van der Weyden',y:'c. 1435',where:'Museo del Prado, Madrid'},{t:'Hunters in the Snow',a:'Pieter Bruegel the Elder',y:'1565',where:'Kunsthistorisches Museum, Vienna'}],market:{state:'steady',note:'Northern panels sell in the Old Master sales of Christie’s, Sotheby’s and Dorotheum in London, New York and Vienna, with the Brueghel family and the Cranach workshop supplying the most frequent lots, and attribution and dendrochronology driving price. Memling’s Virgin Mary Nursing the Christ Child set an artist record of £3.46m ($4.6m) at Sotheby’s London on 1 July 2026, while the Brueghel benchmark is Pieter Brueghel the Younger’s Battle between Carnival and Lent at £6.87m ($10.7m) in 2011.',record:'Pieter Brueghel the Younger, The Battle between Carnival and Lent: $10.7m, Christie’s, London, 6 Dec 2011',recordSrc:'https://artslife.com/2011/12/06/dipinti-antichi-4/'},links:['gothic','earlyren','dutchgolden','baroque'],sources:[['Met Heilbrunn Timeline: Painting in Oil in the Low Countries and Its Spread to Southern Europe','https://www.metmuseum.org/toah/hd/oilp/hd_oilp.htm'],['ArtsLife: Christie’s London Old Master evening sale results, 6 December 2011','https://artslife.com/2011/12/06/dipinti-antichi-4/'],['ArtPro: Sotheby’s London Old Master evening sale results, 1 July 2026 (Memling)','https://share.artpro.com/explore_share/4d/ad/4dad0c027fe9d5ca70136edf9a3f5a6b.html']],vf:'V'},
{id:'highren',n:'High Renaissance',from:1490,to:1527,place:'Florence, Rome and Venice',what:'The short classic phase of Italian art from about 1490 to the Sack of Rome in 1527, led by Leonardo, Michelangelo and Raphael in Florence and Rome and by Giorgione and Titian in Venice. Its core idea was ideal harmony: nature perfected through geometry, anatomy and classical models.',why:'It fixed the ’grand manner’ that European academies taught for four centuries. Venice added colour and oil on canvas, which became the standard medium of European painting.',look:'Pyramidal compositions, soft sfumato modelling, monumental idealised figures, unified light and, in Venice, oil on canvas with rich glazed colour.',artists:['Leonardo da Vinci','Raphael','Michelangelo','Titian','Giorgione','Andrea del Sarto','Fra Bartolomeo'],works:[{t:'Mona Lisa',a:'Leonardo da Vinci',y:'c. 1503–19',where:'Musée du Louvre, Paris'},{t:'Sistine Chapel ceiling',a:'Michelangelo',y:'1508–12',where:'Sistine Chapel, Vatican City'},{t:'The School of Athens',a:'Raphael',y:'1509–11',where:'Stanza della Segnatura, Vatican Palace'}],market:{state:'thin',note:'Autograph paintings by Leonardo, Raphael, Michelangelo or Titian almost never reach auction, so the market runs on drawings, workshop pictures and contested attributions in the Old Master sales of Christie’s and Sotheby’s in New York and London. Leonardo’s Salvator Mundi, hammered at $400m and sold for $450.3m with fees at Christie’s New York in 2017, remains the highest auction price for any work of art, ahead of the $236m paid for Klimt’s Portrait of Elisabeth Lederer in 2025, and its attribution is still debated.',record:'Leonardo da Vinci, Salvator Mundi, c. 1500: $450.3m, Christie’s, New York, 15 Nov 2017',recordSrc:'https://www.theartnewspaper.com/2017/11/15/leonardos-salvator-mundi-sells-for-dollar450m-at-christies-new-york'},links:['earlyren','mannerism','baroque','neoclassicism'],sources:[['Met Heilbrunn Timeline: Leonardo da Vinci (1452–1519)','https://www.metmuseum.org/toah/hd/leon/hd_leon.htm'],['The Art Newspaper: Salvator Mundi sells for $450m at Christie’s New York (2017)','https://www.theartnewspaper.com/2017/11/15/leonardos-salvator-mundi-sells-for-dollar450m-at-christies-new-york'],['Art Basel: Art Basel and UBS Global Art Market Report 2026, key trends','https://www.artbasel.com/stories/art-basel-and-ubs-global-art-market-report-2026-art-market-trends']],vf:'V'},
{id:'mannerism',n:'Mannerism',from:1520,to:1600,place:'Florence, Rome, Parma and Fontainebleau',what:'The style that followed the High Renaissance in Florence, Rome, Parma and the French court at Fontainebleau from about 1520 to 1600. Its core idea was artifice over nature: elongated bodies, twisting poses, acid colour and ambiguous space, prized as proof of maniera, or stylish virtuosity.',why:'It broke the High Renaissance balance and made the artist’s invention, rather than nature, the measure of quality. Through Fontainebleau and engravings it spread a courtly international style, and its tensions fed El Greco and the early Baroque.',look:'Serpentine figures (figura serpentinata), elongated necks and hands, crowded or tilted space, cold enamel-like colour, and polished, aloof portraits.',artists:['Jacopo Pontormo','Agnolo Bronzino','El Greco','Parmigianino','Rosso Fiorentino','Giulio Romano','Giambologna'],works:[{t:'Deposition from the Cross',a:'Jacopo Pontormo',y:'1525–28',where:'Capponi Chapel, Santa Felicita, Florence'},{t:'Madonna with the Long Neck',a:'Parmigianino',y:'1534–40',where:'Uffizi Galleries, Florence'},{t:'An Allegory with Venus and Cupid',a:'Agnolo Bronzino',y:'c. 1545',where:'National Gallery, London'}],market:{state:'thin',note:'Mannerist paintings reach the Old Master evening sales in New York and London only a few times a decade; most supply is drawings, bronzes after Giambologna and workshop portraits, and Florentine portraits by Pontormo and Bronzino are among the scarcest Old Masters of all. The verified auction benchmark is still the Getty’s purchase of Pontormo’s Portrait of a Halberdier for $35.2m at Christie’s New York in 1989, which tripled the previous Old Master record.',record:'Jacopo Pontormo, Portrait of a Halberdier, c. 1528–30: $35.2m, Christie’s, New York, 31 May 1989',recordSrc:'https://juddtully.net/?p=623'},links:['highren','baroque','earlyren'],sources:[['Met Heilbrunn Timeline: Mannerism: Bronzino (1503–1572) and His Contemporaries','https://www.metmuseum.org/toah/hd/zino/hd_zino.htm'],['Getty Publications: Pontormo, Portrait of a Halberdier','https://www.getty.edu/publications/virtuallibrary/0892363665.html'],['Judd Tully: Old Master nets record $35 million; Pontormo portrait sold to Getty (1989)','https://juddtully.net/?p=623']],vf:'V'},
{id:'baroque',n:'Baroque',from:1600,to:1700,place:'Rome, Antwerp, Madrid and Seville',what:'The dominant style of Catholic Europe from about 1600 to 1700, born in Rome with Caravaggio and the Carracci and carried to Antwerp by Rubens and van Dyck and to Madrid and Seville by Velázquez, Zurbarán and Murillo. Its core idea was persuasion: dramatic light, movement and direct emotional appeal in the service of the Counter-Reformation Church and absolutist courts.',why:'Caravaggio’s naturalism and deep shadow spread across Europe within a generation, and Rubens ran a studio on an industrial scale. In Rome, Bernini fused painting, sculpture and architecture into total environments.',look:'Strong chiaroscuro and raking light, diagonal compositions, life-size figures pressed to the picture plane, fluid brushwork in Rubens, and in Spain dark grounds with sober realism.',artists:['Peter Paul Rubens','Anthony van Dyck','Caravaggio','Artemisia Gentileschi','Diego Velázquez','Bartolomé Esteban Murillo','Gian Lorenzo Bernini'],works:[{t:'The Calling of Saint Matthew',a:'Caravaggio',y:'1599–1600',where:'Contarelli Chapel, San Luigi dei Francesi, Rome'},{t:'The Elevation of the Cross',a:'Peter Paul Rubens',y:'1610–11',where:'Cathedral of Our Lady, Antwerp'},{t:'Las Meninas',a:'Diego Velázquez',y:'1656',where:'Museo del Prado, Madrid'}],market:{state:'steady',note:'Baroque pictures are the backbone of the Old Master sales of Christie’s, Sotheby’s and Dorotheum in London, New York and Vienna and of TEFAF Maastricht; Rubens oil sketches, van Dyck portraits and Caravaggesque canvases trade most often, and women painters such as Artemisia Gentileschi have been re-rated upward. Old Master auction sales rose 30% in 2025, but the category record is still Rubens’s Massacre of the Innocents, sold for $76.2m at Sotheby’s London in 2002.',record:'Peter Paul Rubens, The Massacre of the Innocents, c. 1610: $76.2m, Sotheby’s, London, 10 Jul 2002',recordSrc:'https://www.cbsnews.com/news/he-wouldnt-be-starving-anymore/'},links:['mannerism','dutchgolden','rococo','northernren'],sources:[['Met Heilbrunn Timeline: Baroque Rome','https://www.metmuseum.org/toah/hd/barr/hd_barr.htm'],['Met Heilbrunn Timeline: Peter Paul Rubens (1577–1640)','https://www.metmuseum.org/toah/hd/rube/hd_rube.htm'],['CBS News (AP): Rubens’ Massacre of the Innocents sells for $76.2 million (2002)','https://www.cbsnews.com/news/he-wouldnt-be-starving-anymore/'],['Artlyst: Art Basel and UBS Art Market Report 2026 (2025 figures)','https://artlyst.com/art-basel-ubs-global-art-market-2026-reports-59-6-billion-recovery/']],vf:'V'},
{id:'dutchgolden',n:'Dutch Golden Age',from:1600,to:1680,place:'Dutch Republic (Amsterdam, Haarlem, Delft, Leiden)',what:'Painting in the Protestant Dutch Republic from about 1600 to 1680, when a prosperous trading society bought pictures on an open market rather than through church or court commissions. Its core idea was the observed world, in portraits, landscapes, still lifes, interiors and genre scenes painted with great finesse and often with a moral undertone.',why:'It created the modern art market of dealers, specialist genres and middle-class buyers, with millions of paintings produced. Rembrandt, Hals and Vermeer made everyday subjects and psychological portraiture into high art.',look:'Oil on oak panel or canvas, specialist genres, tonal landscapes with low horizons, symbolic still lifes, cool daylight interiors, and in Rembrandt thick impasto and deep shadow; signatures and dates matter.',artists:['Rembrandt van Rijn','Frans Hals','Johannes Vermeer','Jacob van Ruisdael','Jan Steen','Ambrosius Bosschaert the Elder','Pieter de Hooch'],works:[{t:'The Laughing Cavalier',a:'Frans Hals',y:'1624',where:'Wallace Collection, London'},{t:'The Night Watch',a:'Rembrandt van Rijn',y:'1642',where:'Rijksmuseum, Amsterdam'},{t:'Girl with a Pearl Earring',a:'Johannes Vermeer',y:'c. 1665',where:'Mauritshuis, The Hague'}],market:{state:'steady',note:'Dutch pictures are the deepest pool in the Old Master trade, sold by Christie’s and Sotheby’s in London and New York and by dealers at TEFAF Maastricht, with still lifes, landscapes and genre scenes forming a liquid middle market. Masterpieces are scarce: Rembrandt’s auction record of £20.2m ($33.2m) was set in 2009, and Old Master auction sales rose 30% in 2025.',record:'Rembrandt van Rijn, Portrait of a Man with Arms Akimbo, 1658: $33.2m, Christie’s, London, 8 Dec 2009',recordSrc:'https://theartwolf.com/news/raphael-rembrandt-christies/'},links:['northernren','baroque','realism','impressionism'],sources:[['Met Heilbrunn Timeline: Dutch Painting in the Seventeenth Century','https://www.metmuseum.org/toah/hd/dpts/hd_dpts.htm'],['Met Heilbrunn Timeline: Rembrandt (1606–1669): Paintings','https://www.metmuseum.org/toah/hd/rmbt/hd_rmbt.htm'],['The Art Wolf: Rembrandt world record at Christie’s London (2009)','https://theartwolf.com/news/raphael-rembrandt-christies/'],['Artlyst: Art Basel and UBS Art Market Report 2026 (2025 figures)','https://artlyst.com/art-basel-ubs-global-art-market-2026-reports-59-6-billion-recovery/']],vf:'V'},
{id:'rococo',n:'Rococo',from:1715,to:1775,place:'Paris, Venice and southern Germany',what:'A light, decorative style that began in Paris after the death of Louis XIV in 1715 and spread to Venice, southern Germany and Central Europe until about 1775. Its core idea was pleasure and intimacy: playful ornament, pale colour and scenes of love, leisure and fantasy for private salons.',why:'It moved patronage from the royal court to aristocratic and financier town houses and created new genres such as Watteau’s fête galante. In Venice, Tiepolo carried it onto vast ceilings, and the view painters sold the city to Grand Tour travellers.',look:'Asymmetric rocaille ornament, S- and C-curves, pastel pinks and blues, feathery brushwork, pastel portraits, and in Venice luminous skies and invented capriccio views.',artists:['Francesco Guardi','Canaletto','Jean-Honoré Fragonard','François Boucher','Antoine Watteau','Giovanni Battista Tiepolo','Rosalba Carriera'],works:[{t:'Pilgrimage to Cythera',a:'Antoine Watteau',y:'1717',where:'Musée du Louvre, Paris'},{t:'Allegory of the Planets and Continents (staircase ceiling)',a:'Giovanni Battista Tiepolo',y:'1752–53',where:'Würzburg Residence, Germany'},{t:'The Swing',a:'Jean-Honoré Fragonard',y:'c. 1767',where:'Wallace Collection, London'}],market:{state:'steady',note:'Venetian view painting is the strongest part of the 18th-century market, sold in the July and December Old Master sales in London, while French Rococo canvases, pastels and drawings trade in Paris and New York to a narrower, older buyer base. The category benchmark is Guardi’s view of the Rialto Bridge, which made £26.7m ($42.8m) at Sotheby’s London in 2011, beating Canaletto’s £18.6m record, and was then placed under a UK export bar.',record:'Francesco Guardi, Venice, a View of the Rialto Bridge, Looking North, from the Fondamenta del Carbon: $42.8m, Sotheby’s, London, 6 Jul 2011',recordSrc:'https://artfixdaily.com/news_feed/2011/07/11/5927-guardi-fetches-record-43m-at-london-auction'},links:['baroque','neoclassicism','academic'],sources:[['Britannica: Rococo','https://www.britannica.com/art/Rococo'],['Artfix Daily: Guardi fetches record $43m at London auction (2011)','https://artfixdaily.com/news_feed/2011/07/11/5927-guardi-fetches-record-43m-at-london-auction'],['Artfix Daily: £26.7m Guardi painting barred from export (2011)','https://artfixdaily.com/news_feed/2011/10/17/8697-%C2%A3267m-guardi-painting-barred-from-export']],vf:'V'},
{id:'neoclassicism',n:'Neoclassicism',from:1760,to:1830,place:'Rome, Paris and London',what:'A return to the forms and moral seriousness of Greek and Roman art that took shape in Rome in the 1750s and 1760s, prompted by the excavations at Herculaneum and Pompeii and the writings of Johann Joachim Winckelmann, and dominated Europe until about 1830. Its core idea was ’noble simplicity and quiet grandeur’: clear outline, still composition and civic virtue, set against Rococo frivolity.',why:'It became the visual language of the Enlightenment, the French Revolution and Napoleon’s empire, from David’s Oath of the Horatii to imperial portraiture. It also shaped academies, public museums and civic architecture from St Petersburg to Washington.',look:'Crisp contours, frieze-like compositions, a smooth enamel finish with hidden brushwork, antique dress and settings, and white marble sculpture with idealised features.',artists:['Antonio Canova','Jacques-Louis David','Jean-Auguste-Dominique Ingres','Angelica Kauffman','Pompeo Batoni','Bertel Thorvaldsen','Anton Raphael Mengs'],works:[{t:'Oath of the Horatii',a:'Jacques-Louis David',y:'1784',where:'Musée du Louvre, Paris'},{t:'Cornelia, Mother of the Gracchi',a:'Angelica Kauffman',y:'c. 1785',where:'Virginia Museum of Fine Arts, Richmond'},{t:'Paolina Borghese as Venus Victrix',a:'Antonio Canova',y:'1805–08',where:'Galleria Borghese, Rome'}],market:{state:'steady',note:'Neoclassical paintings and marbles sell in the Old Master and 19th-century sales of Christie’s and Sotheby’s in London, New York and Paris and in their European sculpture and furniture sales, with Grand Tour portraits by Batoni and Kauffman the most liquid. Major works by David, Ingres or Canova rarely reach auction and usually go to museums by private treaty or state pre-emption, so there is no verified recent auction benchmark; Old Master auction sales overall rose 30% in 2025.'},links:['greekroman','rococo','romanticism','academic'],sources:[['Met Heilbrunn Timeline: Neoclassicism','https://www.metmuseum.org/toah/hd/neoc_1/hd_neoc_1.htm'],['Britannica: Neoclassical art','https://www.britannica.com/art/Neoclassical-art'],['Artlyst: Art Basel and UBS Art Market Report 2026 (2025 figures)','https://artlyst.com/art-basel-ubs-global-art-market-2026-reports-59-6-billion-recovery/']],vf:'V'},
{id:'romanticism',n:'Romanticism',from:1790,to:1850,place:'Britain, Germany, France and Spain',what:'A European movement of about 1790 to 1850 that put feeling, imagination and the individual above reason and rules, in reaction to the Enlightenment and industrial change. Its painters sought the sublime in nature, history, the exotic and the irrational, from Turner and Constable in England and Friedrich in Germany to Géricault and Delacroix in France and Goya in Spain.',why:'It made landscape a vehicle for spiritual and political meaning and gave colour and brushwork expressive independence. Turner’s late light and Delacroix’s colour lead directly to Impressionism.',look:'Dramatic skies and seas, small figures dwarfed by nature, loose visible brushwork, saturated colour, ruins and moonlight, and contemporary or exotic subjects charged with emotion.',artists:['J.M.W. Turner','John Constable','Eugène Delacroix','Caspar David Friedrich','Théodore Géricault','Francisco Goya','Ivan Aivazovsky'],works:[{t:'Wanderer above the Sea of Fog',a:'Caspar David Friedrich',y:'c. 1817',where:'Hamburger Kunsthalle, Hamburg'},{t:'The Raft of the Medusa',a:'Théodore Géricault',y:'1818–19',where:'Musée du Louvre, Paris'},{t:'The Fighting Temeraire',a:'J.M.W. Turner',y:'1839',where:'National Gallery, London'}],market:{state:'steady',note:'Romantic pictures sell in the British and Old Master sales of Christie’s and Sotheby’s in London and in 19th-century European sales in New York and Paris; Turner and Constable are the blue chips, Friedrich almost never appears, and Aivazovsky has a deep market of his own. The next test comes on 9 December 2026, when Sotheby’s London re-offers Turner’s Rome, from Mount Aventine at an estimate of about £50m, against the £30.3m ($47.4m) it made in 2014.',record:'J.M.W. Turner, Rome, from Mount Aventine, 1835: $47.4m, Sotheby’s, London, 3 Dec 2014',recordSrc:'https://news.artnet.com/?p=188713'},links:['neoclassicism','realism','prerapha','impressionism'],sources:[['Met Heilbrunn Timeline: Romanticism','https://www.metmuseum.org/toah/hd/roma/hd_roma.htm'],['Tate: Romanticism (art term)','https://www.tate.org.uk/art/art-terms/r/romanticism'],['Artnet News: New world record for J.M.W. Turner (2014)','https://news.artnet.com/?p=188713'],['Finestre sull’Arte: Sotheby’s to auction Turner at about £50m (October 2026)','https://www.finestresullarte.info/en/market/sotheby-s-is-auctioning-a-turner-worth-50-million-pounds-the-masterpiece-is-set-to-break-a-new-record']],vf:'V'},
{id:'realism',n:'Realism and Barbizon',from:1830,to:1880,place:'France (Paris and the Forest of Fontainebleau)',what:'A French movement of about 1830 to 1880 in which the Barbizon painters took their easels into the Forest of Fontainebleau, while Courbet, Millet and Daumier painted peasants, workers and ordinary life on the scale once reserved for history painting. Its core idea was truth to the contemporary world, without idealisation.',why:'Courbet’s Burial at Ornans and his independent Pavilion of Realism of 1855 challenged the Salon’s hierarchy of genres and cast the artist as an independent, even political, figure. Barbizon open-air study prepared Impressionism, and Realism spread to Germany, Russia and America.',look:'Earthy palettes, thick palette-knife paint in Courbet, unidealised working figures, plein-air oil sketches of forest and field, and large canvases of everyday scenes.',artists:['Jean-Baptiste-Camille Corot','Gustave Courbet','Jean-François Millet','Rosa Bonheur','Honoré Daumier','Théodore Rousseau','Charles-François Daubigny'],works:[{t:'A Burial at Ornans',a:'Gustave Courbet',y:'1849–50',where:'Musée d’Orsay, Paris'},{t:'The Horse Fair',a:'Rosa Bonheur',y:'1852–55',where:'Metropolitan Museum of Art, New York'},{t:'The Gleaners',a:'Jean-François Millet',y:'1857',where:'Musée d’Orsay, Paris'}],market:{state:'steady',note:'Realist and Barbizon pictures now sell mostly within combined Old Master and 19th-century sales in London, Paris and New York, with Corot and Courbet the most liquid names; most Courbets make $10,000–200,000, fewer than 2% of his lots pass $1m, and prices have been broadly flat since the 1980s boom. His record is Femme nue couchée, which made $15.3m at Christie’s New York in 2015, and large Realist canvases rarely leave museums.',record:'Gustave Courbet, Femme nue couchée, 1862: $15.3m, Christie’s, New York, 9 Nov 2015',recordSrc:'https://zh.artprice.com/artmarketinsight/events-marking-gustave-courbets-bicentennial-could-stimulate-his-market'},links:['romanticism','peredvizhniki','impressionism','academic'],sources:[['Met Heilbrunn Timeline: Nineteenth-Century French Realism','https://www.metmuseum.org/toah/hd/rlsm/hd_rlsm.htm'],['Met Heilbrunn Timeline: The Barbizon School: French Painters of Nature','https://www.metmuseum.org/toah/hd/bfpn/hd_bfpn.htm'],['Artprice: Courbet’s market at his bicentennial (2019)','https://zh.artprice.com/artmarketinsight/events-marking-gustave-courbets-bicentennial-could-stimulate-his-market'],['Artnet News: Christie’s Artist’s Muse sale sets Courbet record (2015)','https://news.artnet.com/market/christies-artists-muse-sale-491-million-359576']],vf:'V'},
{id:'peredvizhniki',n:'Peredvizhniki (the Wanderers)',from:1870,to:1923,place:'Russia (St Petersburg and Moscow)',what:'The Association of Travelling Art Exhibitions was founded in 1870 by Ivan Kramskoi, Grigory Myasoyedov and others, several of whom had walked out of the St Petersburg Academy in the 1863 ’Revolt of the Fourteen’, and it sent its shows around the Russian Empire until 1923. Its core idea was art as social conscience: realist scenes of Russian life, history and landscape for a wide public, free of Academy control.',why:'It created a national school with its own market, backed by Pavel Tretyakov, who bought its work for the gallery he gave to Moscow in 1892. Its realism later became the official model for Soviet Socialist Realism.',look:'Narrative realism with psychologically sharp faces, muted earth palettes, vast Russian landscapes and seasons, and history or village scenes with a moral or political charge.',artists:['Ilya Repin','Ivan Shishkin','Isaac Levitan','Arkhip Kuindzhi','Ivan Kramskoi','Vasily Surikov','Vasily Polenov'],works:[{t:'Barge Haulers on the Volga',a:'Ilya Repin',y:'1870–73',where:'State Russian Museum, St Petersburg'},{t:'Boyarynya Morozova',a:'Vasily Surikov',y:'1887',where:'State Tretyakov Gallery, Moscow'},{t:'Morning in a Pine Forest',a:'Ivan Shishkin and Konstantin Savitsky',y:'1889',where:'State Tretyakov Gallery, Moscow'}],market:{state:'cooling',note:'Until 2022 the Wanderers sold mainly in the June and November Russian art weeks in London at Christie’s, Sotheby’s, Bonhams and MacDougall’s; since the invasion of Ukraine and sanctions the large houses have stepped back, and trade has moved to Moscow auctions and smaller European rooms. Museum-quality pictures rarely leave Russia, and the verified benchmark is still Repin’s A Parisian Café, sold for £4.5m ($7.4m) at Christie’s London in 2011.',record:'Ilya Repin, A Parisian Café, 1875: $7.4m, Christie’s, London, 6 Jun 2011',recordSrc:'https://www.foxnews.com/world/repin-painting-sells-for-7-4-million'},links:['realism','miriskusstva','russianavantgarde','academic'],sources:[['Fox News (AP): Repin painting sells for $7.4 million (2011)','https://www.foxnews.com/world/repin-painting-sells-for-7-4-million'],['Kyiv Post: Christie’s sets Repin record in Russian art sale (2011)','https://archive.kyivpost.com/article/content/eastern-europe/christies-sets-repin-record-in-russian-art-sale-106118.html']],vf:'V'},
{id:'prerapha',n:'Pre-Raphaelites',from:1848,to:1900,place:'London and Oxford, England',what:'A brotherhood founded in London in 1848 by Dante Gabriel Rossetti, John Everett Millais and William Holman Hunt, who rejected the Royal Academy’s conventions, derived from Raphael, in favour of the bright colour and close detail of early Italian and Northern art. Its core idea was truth to nature joined to moral, literary and medieval subjects; a second phase led by Rossetti, Burne-Jones and Morris turned to a dreamy Aestheticism.',why:'It was Britain’s first avant-garde, defended by John Ruskin, and its later phase fed Symbolism and the Arts and Crafts movement. Painting over a white ground gave its pictures a jewel-like brilliance new to English art.',look:'Brilliant colour over a white ground, botanical detail painted from nature, shallow space, medieval and Arthurian subjects, and in late Rossetti long-necked women with heavy hair and sensual features.',artists:['John William Waterhouse','Dante Gabriel Rossetti','Edward Burne-Jones','John Everett Millais','William Holman Hunt','Ford Madox Brown','Evelyn De Morgan'],works:[{t:'Ophelia',a:'John Everett Millais',y:'1851–52',where:'Tate Britain, London'},{t:'The Light of the World',a:'William Holman Hunt',y:'1851–53',where:'Keble College, Oxford'},{t:'Proserpine',a:'Dante Gabriel Rossetti',y:'1874',where:'Tate Britain, London'}],market:{state:'steady',note:'Pre-Raphaelite and Victorian pictures sell in the British art sales of Christie’s and Sotheby’s in London to collectors in Britain and the United States; finished oils by Rossetti, Burne-Jones and Waterhouse are scarce, so drawings, studies and followers keep the market liquid. The benchmark is still Waterhouse’s St Cecilia, bought for Andrew Lloyd Webber at Christie’s London in 2000 for £6.6m, then a record for a Victorian painting.',record:'John William Waterhouse, St Cecilia, 1895: c.$9.9m (£6.6m), Christie’s, London, 2000',recordSrc:'https://www.deseret.com/2000/6/16/19512980/lloyd-webber-buys-painting-for-9-million'},links:['romanticism','symbolism','artsandcrafts','academic'],sources:[['Tate: Pre-Raphaelite (art term)','https://www.tate.org.uk/art/art-terms/p/pre-raphaelite'],['Deseret News (AP): Lloyd Webber buys painting for $9 million (2000)','https://www.deseret.com/2000/6/16/19512980/lloyd-webber-buys-painting-for-9-million'],['JohnWilliamWaterhouse.com: Collecting Waterhouse paintings today','https://www.johnwilliamwaterhouse.com/articles/waterhouse-collectors-today']],vf:'S'},
{id:'ukiyoe',n:'Ukiyo-e',from:1670,to:1900,place:'Edo (Tokyo), Japan',what:'’Pictures of the floating world’: woodblock prints and paintings made in Edo (now Tokyo) from the late 17th century to about 1900, showing courtesans, kabuki actors, the pleasure quarters and, later, landscapes. It was a commercial art for an urban merchant public, produced by a team of publisher, designer, carver and printer.',why:'Full-colour ’brocade prints’ from 1765 and the landscape series of Hokusai and Hiroshige in the 1830s made it a mass medium. After Japan opened to the West in the 1850s, the prints reached Paris and shaped Japonisme, Impressionism and Post-Impressionism.',look:'Flat areas of colour, bold outlines, asymmetric and cropped compositions, imported Prussian blue from the late 1820s, and publisher’s and censor’s seals; value turns on an early impression, fresh colour and condition.',artists:['Katsushika Hokusai','Utagawa Hiroshige','Kitagawa Utamaro','Tōshūsai Sharaku','Suzuki Harunobu','Utagawa Kuniyoshi','Torii Kiyonaga'],works:[{t:'Three Beauties of the Present Day',a:'Kitagawa Utamaro',y:'c. 1792–93',where:'Impressions in several museums, including the British Museum, London'},{t:'Under the Wave off Kanagawa (The Great Wave)',a:'Katsushika Hokusai',y:'c. 1830–32',where:'Impressions in several museums, including the Metropolitan Museum of Art, New York'},{t:'Sudden Shower over Shin-Ōhashi Bridge and Atake',a:'Utagawa Hiroshige',y:'1857',where:'Impressions in several museums, including the Brooklyn Museum, New York'}],market:{state:'heating',note:'Ukiyo-e trades in the Japanese art sales of Christie’s and Sotheby’s in New York, London, Paris and Hong Kong and through specialist dealers, and early, fresh impressions of Hokusai’s and Hiroshige’s best-known designs have risen sharply as Asian and Western buyers compete. A Great Wave made $2.76m at Christie’s New York in March 2023, a complete Thirty-six Views of Mount Fuji made $3.5m at Christie’s New York in 2024, and another Great Wave reached HK$21.7m ($2.8m) at Sotheby’s Hong Kong in November 2025.',record:'Katsushika Hokusai, Under the Wave off Kanagawa (The Great Wave), c. 1831: $2.8m, Sotheby’s, Hong Kong, 22 Nov 2025',recordSrc:'https://www.tokyoweekender.com/?p=279228'},links:['chineseink','impressionism','postimpressionism','artsandcrafts'],sources:[['Met Heilbrunn Timeline: Woodblock Prints in the Ukiyo-e Style','https://www.metmuseum.org/toah/hd/ukiy/hd_ukiy.htm'],['Artprice: Hokusai’s Great Wave reaches a new milestone (2023)','https://www.artprice.com/artmarketinsight/hokusais-great-wave-reaches-a-new-milestone'],['The Peak: Hokusai’s Great Wave sold for three times its estimate at Sotheby’s (2025)','https://www.thepeakmagazine.com.sg/influence/hokusais-great-wave-sold-three-times-its-estimate-sothebys-its-cultural-significance-fuels-collector'],['Tokyo Weekender: Hokusai’s Great Wave sells for record amount at Sotheby’s (2025)','https://www.tokyoweekender.com/?p=279228']],vf:'V'},
{id:'chineseink',n:'Chinese ink painting',from:960,to:1912,place:'China',what:'Painting in ink and light colour on silk and paper in which, from the Song dynasty (960–1279), scholar-officials turned brushwork into self-expression and set it against the polished art of court professionals. Carried through the Yuan masters, the Ming Wu School and the Qing Orthodox and Individualist painters to 1912, its core idea was that a painting reveals the character of its maker.',why:'It made calligraphic brushwork, poetry and painting a single art, so inscriptions, seals and colophons added by later owners became part of the work. The canon of styles it set still frames how Chinese collectors judge quality and price.',look:'Ink monochrome or light colour on paper or silk in handscroll, hanging-scroll or album form, texture strokes (cun) in rocks and mountains, inscribed poems, and the seals of artist and later owners that record provenance.',artists:['Wu Bin','Su Shi','Shen Zhou','Wen Zhengming','Dong Qichang','Zhao Mengfu','Ni Zan'],works:[{t:'Autumn Colours on the Qiao and Hua Mountains',a:'Zhao Mengfu',y:'1296',where:'National Palace Museum, Taipei'},{t:'Dwelling in the Fuchun Mountains',a:'Huang Gongwang',y:'1347–50',where:'National Palace Museum, Taipei, and Zhejiang Provincial Museum, Hangzhou'},{t:'The Qingbian Mountains',a:'Dong Qichang',y:'1617',where:'Cleveland Museum of Art'}],market:{state:'steady',note:'Classical painting and calligraphy sell at Poly and China Guardian in Beijing and at Christie’s and Sotheby’s in Hong Kong, overwhelmingly to Chinese buyers, with seals, colophons and imperial provenance driving price and late payment a known risk. China accounted for about 14% of global art sales in 2025, and the classical record is Wu Bin’s Ten Views of a Lingbi Rock, which in 1989 became the first Chinese painting to sell for over $1m at Sotheby’s and in 2020 made RMB 512.9m ($76.6m) at Poly Beijing.',record:'Wu Bin, Ten Views of a Lingbi Rock, 1610: $76.6m, Poly Auction, Beijing, 18 Oct 2020',recordSrc:'https://global.chinadaily.com.cn/a/202010/19/WS5f8d3bcfa31024ad0ba7f966.html'},links:['ukiyoe','abex'],sources:[['Met Heilbrunn Timeline: Landscape Painting in Chinese Art','https://www.metmuseum.org/toah/hd/clpg/hd_clpg.htm'],['Norton Museum of Art: Wu Bin’s Ten Views of a Lingbi Rock','https://www.norton.org/events/virtual-curator-conversation-wu-bins-ten-views-of-a-lingbi-rock-rediscovering-a-masterpiece-that-was-never-actually-lost-11-18-2020'],['China Daily: Chinese artwork sells for record price of $77m (2020)','https://global.chinadaily.com.cn/a/202010/19/WS5f8d3bcfa31024ad0ba7f966.html'],['Art Basel: Art Basel and UBS Global Art Market Report 2026, key trends','https://www.artbasel.com/stories/art-basel-and-ubs-global-art-market-report-2026-art-market-trends']],vf:'V'},
{id:'academic',n:'Academic and Salon painting',from:1830,to:1900,place:'Paris, London, Munich and St Petersburg',what:'The art taught by the academies and shown at the Paris Salon, the Royal Academy in London and their counterparts in Munich and St Petersburg, at its height from about 1830 to 1900. Its core idea was mastery of drawing, anatomy and finish in the service of history, mythology, Orientalist and genre subjects, ranked by a strict hierarchy of genres.',why:'The Salon was the main route to fame, state purchases and private buyers, and its medals created the first international art stars. Its rejection of Manet and the future Impressionists, most visibly at the 1863 Salon des Refusés, made it the foil against which modern art defined itself.',look:'Invisible brushwork and porcelain-smooth flesh, precise drawing, archaeological detail of costume and setting, large and highly finished canvases, and idealised nudes in mythological guise.',artists:['Lawrence Alma-Tadema','William-Adolphe Bouguereau','Jean-Léon Gérôme','Ivan Aivazovsky','Alexandre Cabanel','Frederic Leighton','Ernest Meissonier'],works:[{t:'The Birth of Venus',a:'Alexandre Cabanel',y:'1863',where:'Musée d’Orsay, Paris'},{t:'Nymphs and Satyr',a:'William-Adolphe Bouguereau',y:'1873',where:'Clark Art Institute, Williamstown, Massachusetts'},{t:'Flaming June',a:'Frederic Leighton',y:'1895',where:'Museo de Arte de Ponce, Puerto Rico'}],market:{state:'steady',note:'Academic and Salon pictures sell in the 19th-century European and British sales of Christie’s, Sotheby’s and Bonhams in New York and London, increasingly folded into Old Master sales, with Orientalist scenes drawing strong Middle Eastern demand and Bouguereau and Gérôme favoured by American collectors. The top is narrow: Alma-Tadema’s The Finding of Moses made $35.9m at Sotheby’s New York in 2010, more than seven times its high estimate and up from $2.8m in 1995.',record:'Lawrence Alma-Tadema, The Finding of Moses, 1904: $35.9m, Sotheby’s, New York, 4 Nov 2010',recordSrc:'https://artfixdaily.com/news_feed/2010/11/08/3590-sir-lawrence-alma-tadema-masterpiece-fetches-record-359-million'},links:['neoclassicism','realism','impressionism','prerapha'],sources:[['Met Heilbrunn Timeline: The Salon and the Royal Academy in the Nineteenth Century','https://www.metmuseum.org/toah/hd/sara/hd_sara.htm'],['Artfix Daily: Alma-Tadema masterpiece fetches record $35.9 million (2010)','https://artfixdaily.com/news_feed/2010/11/08/3590-sir-lawrence-alma-tadema-masterpiece-fetches-record-359-million']],vf:'V'},
{id:'impressionism',n:'Impressionism',from:1872,to:1890,place:'Paris and the Seine valley, France',what:'A group of Paris-based painters, among them Monet, Renoir, Degas, Pissarro, Sisley, Morisot and Cassatt, who staged eight independent exhibitions between 1874 and 1886 outside the official Salon. Their core idea was to record modern life and the passing effects of light and atmosphere, painting quickly, often outdoors, in broken touches of unmixed colour.',why:'They broke the Salon’s monopoly by mounting their own shows and selling through dealers such as Paul Durand-Ruel, creating the dealer–critic system of modern art. Their handling and colour opened the way for every later modern movement.',look:'Visible broken brushstrokes, light palettes with coloured rather than black shadows, outdoor light and weather, cropped compositions influenced by photography and Japanese prints, and series of one motif at different times of day.',artists:['Claude Monet','Pierre-Auguste Renoir','Edgar Degas','Camille Pissarro','Gustave Caillebotte','Berthe Morisot','Alfred Sisley'],works:[{t:'Impression, Sunrise',a:'Claude Monet',y:'1872',where:'Musée Marmottan Monet, Paris'},{t:'The Dance Class',a:'Edgar Degas',y:'1874',where:'Metropolitan Museum of Art, New York'},{t:'Bal du moulin de la Galette',a:'Pierre-Auguste Renoir',y:'1876',where:'Musée d’Orsay, Paris'}],market:{state:'heating',note:'Impressionism headlines the May and November evening sales in New York and sells in London and Paris to a global pool of collectors in which Asian buyers are increasingly decisive; Impressionist and Post-Impressionist auction sales rose 47% in 2025 on a few high-value works. On 22 October 2026 Monet’s Iris made €50m ($56m) at Sotheby’s Paris, the highest nominal auction price ever paid in France, though Monet’s record remains the $110.7m paid for Meules in 2019.',record:'Claude Monet, Meules, 1890: $110.7m, Sotheby’s, New York, 14 May 2019',recordSrc:'https://www.inquirer.com/arts/claude-monet-haystacks-painting-sothebys-auction-record-20190515.html'},links:['realism','postimpressionism','ukiyoe','academic'],sources:[['Met Heilbrunn Timeline: Impressionism: Art and Modernity','https://www.metmuseum.org/toah/hd/imml/hd_imml.htm'],['The Art Newspaper: Monet’s monumental Iris makes $56m in Paris (October 2026)','https://www.theartnewspaper.com/2026/10/23/monets-monumental-iris-makes-56m-in-paris'],['Philadelphia Inquirer: Monet haystacks painting sets $110.7m record (2019)','https://www.inquirer.com/arts/claude-monet-haystacks-painting-sothebys-auction-record-20190515.html'],['Artlyst: Art Basel and UBS Art Market Report 2026 (2025 figures)','https://artlyst.com/art-basel-ubs-global-art-market-2026-reports-59-6-billion-recovery/']],vf:'V'},
{id:'postimpressionism',n:'Post-Impressionism',from:1886,to:1905,place:'France (Paris, Provence, Brittany) and Tahiti',what:'A label coined by Roger Fry in 1910 for the painters who built on Impressionism and moved beyond it between about 1886 and 1905, above all Cézanne, Seurat, Van Gogh and Gauguin. Each sought the structure or meaning that Impressionism lacked, through geometry, optical colour theory, expressive brushwork or symbolic flat colour.',why:'Cézanne’s construction led to Cubism, Seurat’s divisionism to Fauvist colour, Van Gogh to Expressionism and Gauguin to Symbolism and primitivism. Together they mark the starting point of modern painting.',look:'Constructive parallel strokes and shifting viewpoints in Cézanne, dots of pure colour in Seurat, thick rhythmic impasto in Van Gogh, and flat areas of non-naturalistic colour with dark outlines in Gauguin.',artists:['Paul Cézanne','Vincent van Gogh','Paul Gauguin','Georges Seurat','Henri de Toulouse-Lautrec','Paul Signac','Émile Bernard'],works:[{t:'A Sunday on La Grande Jatte',a:'Georges Seurat',y:'1884–86',where:'Art Institute of Chicago'},{t:'The Starry Night',a:'Vincent van Gogh',y:'1889',where:'Museum of Modern Art, New York'},{t:'Where Do We Come From? What Are We? Where Are We Going?',a:'Paul Gauguin',y:'1897–98',where:'Museum of Fine Arts, Boston'}],market:{state:'steady',note:'Nearly all major Post-Impressionist paintings are in museums, so the few that surface headline the New York evening sales, usually from single-owner collections, while works on paper and minor pictures sustain the trade in London and Paris; Impressionist and Post-Impressionist auction sales rose 47% in 2025. The benchmarks were set in the Paul Allen sale at Christie’s New York in November 2022: Seurat $149.2m, Cézanne $137.8m, Van Gogh $117.2m and Gauguin $105.7m.',record:'Georges Seurat, Les Poseuses, Ensemble (Petite version), 1888: $149.2m, Christie’s, New York, 9 Nov 2022',recordSrc:'https://edition.cnn.com/style/article/paul-allen-collection-christies-auction-record'},links:['impressionism','symbolism','fauvism','cubism'],sources:[['Met Heilbrunn Timeline: Post-Impressionism','https://www.metmuseum.org/toah/hd/poim/hd_poim.htm'],['CNN: Paul Allen collection sets records at Christie’s (2022)','https://edition.cnn.com/style/article/paul-allen-collection-christies-auction-record'],['Artlyst: Art Basel and UBS Art Market Report 2026 (2025 figures)','https://artlyst.com/art-basel-ubs-global-art-market-2026-reports-59-6-billion-recovery/']],vf:'V'},
{id:'symbolism',n:'Symbolism',from:1886,to:1910,place:'Paris, Brussels, Vienna and Oslo',what:'A literary and artistic movement named in Jean Moréas’s manifesto of 1886, which spread from Paris and Brussels across Europe until about 1910. Its core idea was to suggest ideas, dreams and inner states through myth, symbol and mood, rejecting both academic narrative and Impressionist observation.',why:'It gave art a language for the unconscious, desire and death, linking Moreau, Redon and Puvis de Chavannes with Gauguin, Khnopff, Klimt and Munch. It fed Art Nouveau, Expressionism and Surrealism.',look:'Dreamlike or mythic subjects, femmes fatales, isolated enigmatic figures, decorative line and flattened space, charcoal ’noirs’ and pastels in Redon, and jewel-like oils in Moreau.',artists:['Edvard Munch','Odilon Redon','Fernand Khnopff','Gustave Moreau','Arnold Böcklin','Pierre Puvis de Chavannes','Jean Delville'],works:[{t:'Isle of the Dead (third version)',a:'Arnold Böcklin',y:'1883',where:'Alte Nationalgalerie, Berlin'},{t:'The Scream',a:'Edvard Munch',y:'1893',where:'National Museum, Oslo'},{t:'Jupiter and Semele',a:'Gustave Moreau',y:'1894–95',where:'Musée Gustave Moreau, Paris'}],market:{state:'steady',note:'Symbolist works trade in the Impressionist and Modern sales of Christie’s and Sotheby’s in New York and London and in 19th-century and Belgian sales in Paris and Brussels; Redon pastels, Khnopff drawings and Munch prints supply most of the market, and major oils are rare. Its peak price is Munch’s 1895 pastel of The Scream, which made $119.9m at Sotheby’s New York in 2012, then the highest price for any work at auction.',record:'Edvard Munch, The Scream, pastel, 1895: $119.9m, Sotheby’s, New York, 2 May 2012',recordSrc:'https://www.cbsnews.com/newyork/news/munchs-the-scream-fetches-record-119-9-million-at-sothebys-auction/'},links:['prerapha','postimpressionism','viennasecession','expressionism'],sources:[['Met Heilbrunn Timeline: Symbolism','https://www.metmuseum.org/toah/hd/symb/hd_symb.htm'],['CBS New York: Munch’s The Scream fetches record $119.9 million (2012)','https://www.cbsnews.com/newyork/news/munchs-the-scream-fetches-record-119-9-million-at-sothebys-auction/']],vf:'V'},
{id:'artsandcrafts',n:'Arts and Crafts and Art Nouveau',from:1860,to:1914,place:'Britain, Belgium, France and the United States',what:'Two linked design movements: Arts and Crafts, led in Britain from the 1860s by William Morris, which revived handcraft and honest materials against industrial production, and Art Nouveau, which from the early 1890s in Brussels, Paris, Nancy and Glasgow sought a new style based on organic line. Their shared core idea was to unite the fine and applied arts and bring beauty into everyday objects and buildings.',why:'They raised furniture, glass, textiles, posters and jewellery to the status of art and made the designer a modern figure, from Horta and Guimard to Mackintosh and Tiffany. Their ideas fed the Vienna Secession, the Bauhaus and modern design.',look:'Whiplash curves and plant forms, iridescent or cameo glass, hand-worked oak with visible joinery, stylised natural motifs, and makers’ marks or signatures that decide value.',artists:['Louis Comfort Tiffany','Émile Gallé','René Lalique','Alphonse Mucha','Charles Rennie Mackintosh','Hector Guimard','William Morris'],works:[{t:'Strawberry Thief (furnishing textile)',a:'William Morris',y:'1883',where:'Victoria and Albert Museum, London'},{t:'Hôtel Tassel',a:'Victor Horta',y:'1893',where:'Brussels (in situ; UNESCO World Heritage)'},{t:'Paris Métro entrance, Porte Dauphine',a:'Hector Guimard',y:'1900',where:'Paris (in situ)'}],market:{state:'steady',note:'The trade runs through design and decorative-arts sales at Christie’s, Sotheby’s and Bonhams in New York, London and Paris, with Tiffany Studios lamps and Gallé and Daum glass the most liquid names, Mackintosh and Guimard furniture rare, and posters and Lalique glass forming a broad lower tier. The top end firmed in December 2025, when a Tiffany Magnolia floor lamp made $4.4m at Sotheby’s New York, beating the $3.37m paid for a Pond Lily lamp at Christie’s in 2018.',record:'Tiffany Studios (design attributed to Agnes Northrop), Magnolia floor lamp, c. 1910: $4.4m, Sotheby’s, New York, 11 Dec 2025',recordSrc:'https://www.antiquetrader.com/tiffany-leaded-lamp-lights-up-auction-with-new-record'},links:['prerapha','symbolism','viennasecession','ukiyoe'],sources:[['Met Heilbrunn Timeline: Art Nouveau','https://www.metmuseum.org/toah/hd/artn/hd_artn.htm'],['Met Heilbrunn Timeline: Louis Comfort Tiffany (1848–1933)','https://www.metmuseum.org/toah/hd/tiff/hd_tiff.htm'],['Antique Trader: Tiffany leaded lamp sets new record (2025)','https://www.antiquetrader.com/tiffany-leaded-lamp-lights-up-auction-with-new-record'],['Antiques and the Arts Weekly: Christie’s sets Tiffany Studios world auction record (2018)','https://www.antiquesandthearts.com/christies-sets-tiffany-studios-world-auction-record-3372500']],vf:'V'},
{id:'viennasecession',n:'Vienna Secession',from:1897,to:1918,place:'Vienna, Munich and Darmstadt',what:'The Vienna Secession was founded in 1897 by Gustav Klimt, Koloman Moser, Josef Hoffmann, Joseph Maria Olbrich and others who broke with the conservative Künstlerhaus, part of the German-speaking Jugendstil that also flourished in Munich and Darmstadt. Its core idea, inscribed over the door of Olbrich’s Secession building, was ’To every age its art, to art its freedom’, pursued through a total work of art uniting painting, architecture and design.',why:'It made Vienna a capital of modernism and, through the Wiener Werkstätte founded in 1903, a centre of design. Klimt’s gold-ground portraits and Schiele’s taut, anxious line opened the way to Austrian Expressionism.',look:'Gold and silver leaf, flat ornamental patterns set against naturalistic faces and hands, square formats, black-and-white geometric grids in Hoffmann and Moser design, and erotic, nervous contour in Schiele.',artists:['Gustav Klimt','Egon Schiele','Koloman Moser','Josef Hoffmann','Carl Moll','Joseph Maria Olbrich','Otto Wagner'],works:[{t:'Beethoven Frieze',a:'Gustav Klimt',y:'1902',where:'Secession Building, Vienna'},{t:'The Kiss',a:'Gustav Klimt',y:'1907–08',where:'Belvedere, Vienna'},{t:'Self-Portrait with Physalis',a:'Egon Schiele',y:'1912',where:'Leopold Museum, Vienna'}],market:{state:'heating',note:'Klimt and Schiele headline the Impressionist and Modern evening sales in New York and London, while Wiener Werkstätte silver, glass and furniture by Hoffmann and Moser sell in design sales and at Dorotheum in Vienna; restitution histories shape both supply and price. In November 2025 the Leonard Lauder sale at Sotheby’s New York set the peak: Klimt’s Portrait of Elisabeth Lederer made $236.4m, the second-highest auction price for any work, and his landscapes Flower Meadow and Unterach am Attersee made $86m and $70.8m.',record:'Gustav Klimt, Portrait of Elisabeth Lederer, 1914–16: $236.4m, Sotheby’s, New York, 18 Nov 2025',recordSrc:'https://www.aljazeera.com/news/2025/11/20/gustav-klimt-portrait-breaks-modern-art-record-with-236m-sale'},links:['symbolism','artsandcrafts','expressionism','miriskusstva'],sources:[['Klimt Foundation (Klimt Database): Portrait of Elisabeth Lederer sold at Sotheby’s (2025)','https://www.klimt-database.com/en/news/5065-5/'],['Al Jazeera: Klimt portrait breaks modern art record with $236m sale (2025)','https://www.aljazeera.com/news/2025/11/20/gustav-klimt-portrait-breaks-modern-art-record-with-236m-sale'],['Art Basel: Art Basel and UBS Global Art Market Report 2026, key trends','https://www.artbasel.com/stories/art-basel-and-ubs-global-art-market-report-2026-art-market-trends']],vf:'V'},
{id:'miriskusstva',n:'Mir iskusstva and the Silver Age',from:1898,to:1910,place:'St Petersburg and Paris',what:'An association and magazine founded in St Petersburg in 1898 by Alexandre Benois, Sergei Diaghilev, Léon Bakst and Konstantin Somov, at the centre of the Russian Silver Age that ran to about 1910. Its core idea was art for art’s sake against the Wanderers’ social realism: refined nostalgia for 18th-century Versailles and Petersburg, graphic elegance and the unity of the arts in book design and theatre.',why:'It reconnected Russian art with European Symbolism and Art Nouveau and, through Diaghilev’s exhibitions and the Ballets Russes from 1909, carried Russian design to Paris. Bakst’s and Benois’s stage and costume designs changed European fashion and theatre.',look:'Gouache and watercolour on paper, refined line, nostalgic scenes of Versailles, masquerades and 18th-century parks, book illustration and stage designs in saturated colour, and a decorative stylisation shared with Art Nouveau.',artists:['Nicholas Roerich','Boris Kustodiev','Konstantin Somov','Zinaida Serebriakova','Léon Bakst','Alexandre Benois','Valentin Serov'],works:[{t:'The Lady in Blue (Portrait of Elizaveta Martynova)',a:'Konstantin Somov',y:'1897–1900',where:'State Tretyakov Gallery, Moscow'},{t:'Portrait of Sergei Diaghilev with His Nanny',a:'Léon Bakst',y:'1906',where:'State Russian Museum, St Petersburg'},{t:'Portrait of Ida Rubinstein',a:'Valentin Serov',y:'1910',where:'State Russian Museum, St Petersburg'}],market:{state:'cooling',note:'Silver Age paintings, works on paper and Ballets Russes designs sold for decades in the London Russian art weeks and in theatre and ballet sales in London and Paris; since 2022 the trade has shifted toward Moscow houses and smaller European rooms. The group’s top auction price is Roerich’s late Madonna Laboris (1931), which made £7.9m ($12.1m) at Bonhams London in 2013, then the highest price for a painting at a Russian art sale.',record:'Nicholas Roerich, Madonna Laboris, 1931: $12.1m, Bonhams, London, 5 Jun 2013',recordSrc:'https://www.paulfrasercollectibles.com/blogs/art-photography/roerichs-madonna-laboris-brings-record-12-1m-to-bonhams-russian-sale'},links:['peredvizhniki','symbolism','artsandcrafts','russianavantgarde'],sources:[['Paul Fraser Collectibles: Roerich’s Madonna Laboris brings record $12.1m to Bonhams (2013)','https://www.paulfrasercollectibles.com/blogs/art-photography/roerichs-madonna-laboris-brings-record-12-1m-to-bonhams-russian-sale'],['The Calvert Journal (New East Digital Archive): Most expensive Russian painting at a Russian art auction (2013)','https://www.new-east-archive.org/articles/show/1060/most-expensive-russian-painting-auction-roerich']],vf:'V'},
{id:'fauvism',n:'Fauvism',from:1905,to:1908,place:'Paris and southern France',what:'Fauvism was the first avant-garde movement of the 20th century, named when the critic Louis Vauxcelles called the painters at the 1905 Salon d’Automne in Paris ’fauves’ (wild beasts). Led by Henri Matisse and André Derain, it used pure, unmixed colour and loose brushwork to express feeling rather than describe appearance.',why:'Fauvism freed colour from description and showed that a picture could be built from colour relationships alone. Its lessons passed directly to German Expressionism and, through Matisse, to later abstraction.',look:'Look for flat zones of saturated, non-naturalistic colour (green shadows, red trees), patches of bare canvas and vigorous, broken brushstrokes.',artists:['Henri Matisse','André Derain','Maurice de Vlaminck','Kees van Dongen','Raoul Dufy','Georges Braque','Albert Marquet'],works:[{t:'Woman with a Hat',a:'Henri Matisse',y:'1905',where:'San Francisco Museum of Modern Art'},{t:'Le Bonheur de vivre',a:'Henri Matisse',y:'1905–06',where:'Barnes Foundation, Philadelphia'},{t:'The Pool of London',a:'André Derain',y:'1906',where:'Tate, London'}],market:{state:'steady',note:'True Fauve canvases of 1905–07 are scarce and mostly in museums, so the market runs on Matisse’s later work and on regular supply from Vlaminck, Van Dongen, Dufy and Derain, bought mainly by American, European and Asian private collectors in New York, London and Paris. Matisse’s auction record is $80.8m for the post-Fauve Odalisque couchée aux magnolias (1923), sold from the Rockefeller collection at Christie’s New York in May 2018, and a 1947 ink still life made $4.8m, his top price for ink on paper, at Christie’s New York in May 2026.',record:'Henri Matisse, Odalisque couchée aux magnolias (1923): $80.8m, Christie’s, New York, 8 May 2018',recordSrc:'https://www.voanews.com/a/rockefeller-collection-record-auction/4390890.html'},links:['postimpressionism','expressionism','cubism'],sources:[['Tate: Fauvism','https://www.tate.org.uk/art/art-terms/f/fauvism'],['MoMA: Fauvism','https://www.moma.org/collection/terms/fauvism'],['VOA: Rockefeller sale sets records (May 2018)','https://www.voanews.com/a/rockefeller-collection-record-auction/4390890.html'],['Ocula: Christie’s $1.1bn New York night (May 2026)','https://ocula.com/magazine/art-news/christies-1bn-new-york-auction/']],vf:'V'},
{id:'expressionism',n:'Expressionism: Die Brücke and Der Blaue Reiter',from:1905,to:1914,place:'Dresden, Berlin and Munich',what:'German Expressionism grew from two groups: Die Brücke (The Bridge), founded in Dresden in 1905 by Ernst Ludwig Kirchner, Erich Heckel, Karl Schmidt-Rottluff and Fritz Bleyl, and Der Blaue Reiter (The Blue Rider), formed in Munich in 1911 around Wassily Kandinsky and Franz Marc. Both distorted form and colour to convey inner experience: Die Brücke through raw city scenes and nudes, Der Blaue Reiter through spiritual colour that led Kandinsky to abstraction.',why:'They made emotional intensity, not optical truth, the measure of modern painting and revived the woodcut as a modern medium. Kandinsky’s move to non-objective painting around 1910–13 was a founding step of abstract art, and the Nazi campaign against ’degenerate art’ scattered the work, which still shapes provenance and restitution today.',look:'Look for jagged contours, acid or symbolic colour, mask-like faces, angular woodcut cutting and, in Blaue Reiter work, animals and landscapes dissolving into coloured planes.',artists:['Wassily Kandinsky','Franz Marc','Ernst Ludwig Kirchner','Emil Nolde','August Macke','Karl Schmidt-Rottluff','Gabriele Münter'],works:[{t:'Street, Dresden',a:'Ernst Ludwig Kirchner',y:'1908',where:'Museum of Modern Art, New York'},{t:'The Large Blue Horses',a:'Franz Marc',y:'1911',where:'Walker Art Center, Minneapolis'},{t:'Composition VII',a:'Wassily Kandinsky',y:'1913',where:'State Tretyakov Gallery, Moscow'}],market:{state:'steady',note:'Top paintings surface mainly through restitutions and estates and sell in London and New York to European and American collectors, while prints and works on paper form a broad lower tier in German salerooms. Franz Marc’s restituted The Foxes (1913) set his record at $56.7m at Christie’s London in March 2022, and Kandinsky’s Murnau mit Kirche II (1910) set his at £37.2m at Sotheby’s London in March 2023.',record:'Franz Marc, Die Füchse (The Foxes) (1913): $56.7m, Christie’s, London, 1 Mar 2022',recordSrc:'https://heni.com/news/article/franz-marc-the-foxes-die-fuchse-2022-03-01'},links:['fauvism','viennasecession','neoexpressionism'],sources:[['Tate: Expressionism','https://www.tate.org.uk/art/art-terms/e/expressionism'],['MoMA: Expressionism','https://www.moma.org/collection/terms/expressionism'],['Sotheby’s: Kandinsky record in London (March 2023)','https://sothebys.com/en/articles/kandinsky-munch-and-richter-lead-the-charge-in-london'],['HENI News: Franz Marc, The Foxes (2022)','https://heni.com/news/article/franz-marc-the-foxes-die-fuchse-2022-03-01']],vf:'V'},
{id:'cubism',n:'Cubism',from:1907,to:1914,place:'Paris',what:'Cubism was developed in Paris from 1907 by Pablo Picasso and Georges Braque, who broke objects and figures into faceted planes seen from several viewpoints at once. It moved from an ’analytic’ phase of muted, splintered forms (1909–12) to a ’synthetic’ phase of flatter shapes, collage and papier collé (1912–14), while Juan Gris, Fernand Léger and the Salon Cubists spread it widely.',why:'Cubism abandoned single-point perspective, the basis of Western painting since the Renaissance, and treated the picture as a constructed object. Collage and construction opened the way to Futurism, Constructivism, De Stijl and most later abstraction.',look:'Look for faceted, overlapping planes, a narrow palette of browns, greys and ochres in early works, stencilled letters, and pasted paper or imitation wood grain in later ones.',artists:['Pablo Picasso','Georges Braque','Juan Gris','Fernand Léger','Robert Delaunay','Albert Gleizes','Jean Metzinger'],works:[{t:'Les Demoiselles d’Avignon',a:'Pablo Picasso',y:'1907',where:'Museum of Modern Art, New York'},{t:'Violin and Candlestick',a:'Georges Braque',y:'1910',where:'San Francisco Museum of Modern Art'},{t:'Still Life with Chair Caning',a:'Pablo Picasso',y:'1912',where:'Musée national Picasso-Paris'}],market:{state:'steady',note:'Canvases from 1909–14 are rare and mostly institutional, so Cubism trades through Picasso, Léger and Gris in New York and London evening sales, with a deeper market in works on paper and prints. Picasso’s Femme assise (1909) made £43.3m ($63.6m) at Sotheby’s London in 2016, then a record for a Cubist work, and a 1909 Picasso Tête de femme fetched $14.5m, nearly double its high estimate, at Christie’s New York in May 2026.',record:'Pablo Picasso, Les Femmes d’Alger (Version ’O’) (1955): $179.4m, Christie’s, New York, 11 May 2015',recordSrc:'https://www.npr.org/2022/05/09/1096617152/a-warhol-marilyn-brings-a-record-auction-price-195-million'},links:['postimpressionism','futurism','destijl','russianavantgarde'],sources:[['Tate: Cubism','https://www.tate.org.uk/art/art-terms/c/cubism'],['MoMA: Cubism','https://www.moma.org/collection/terms/cubism'],['Artlyst: Femme assise sets Cubist record (2016)','https://artlyst.com/sothebys-achieves-new-record-price-for-picasso-cubist-work-of-art/'],['Ocula: Christie’s $1.1bn New York night (May 2026)','https://ocula.com/magazine/art-news/christies-1bn-new-york-auction/']],vf:'V'},
{id:'futurism',n:'Futurism',from:1909,to:1944,place:'Milan and Rome',what:'Futurism was launched by Filippo Tommaso Marinetti’s manifesto on the front page of Le Figaro on 20 February 1909 and taken up by the painters Umberto Boccioni, Carlo Carrà, Luigi Russolo, Giacomo Balla and Gino Severini. It glorified speed, machines, the city and war, and painted motion by fusing Cubist fragmentation with Divisionist colour; a ’second Futurism’ continued into the 1940s.',why:'Futurism was the first movement run as a media campaign, with manifestos, provocations and performances that Dada and later avant-gardes copied. It shaped Russian Cubo-Futurism and British Vorticism, though its cult of war and later ties to Fascism complicate its legacy.',look:'Look for repeated, overlapping forms that suggest movement, ’lines of force’, fractured light and subjects such as trains, cars, crowds and dancers.',artists:['Gino Severini','Umberto Boccioni','Giacomo Balla','Carlo Carrà','Luigi Russolo','Fortunato Depero'],works:[{t:'Unique Forms of Continuity in Space',a:'Umberto Boccioni',y:'1913',where:'Museum of Modern Art, New York (bronze cast 1931)'},{t:'Dynamism of a Dog on a Leash',a:'Giacomo Balla',y:'1912',where:'Buffalo AKG Art Museum'},{t:'Dynamic Hieroglyphic of the Bal Tabarin',a:'Gino Severini',y:'1912',where:'Museum of Modern Art, New York'}],market:{state:'thin',note:'Most key paintings of 1910–15 are in museums and Italian export controls keep many privately held works inside Italy, so the market runs on works on paper, later Futurism and rare canvases sold in London and Milan to Italian and international collectors. The benchmark is Severini’s Danseuse (1915), which made £15.0m ($29.6m) at Sotheby’s London in 2008, at the time a record for any Futurist work at auction.',record:'Gino Severini, Danseuse (1915): $29.6m, Sotheby’s, London, 2008',recordSrc:'https://italianfuturism.org/?p=75'},links:['cubism','russianavantgarde','dada'],sources:[['Tate: Futurism','https://www.tate.org.uk/art/art-terms/f/futurism'],['MoMA: Futurism','https://www.moma.org/collection/terms/futurism'],['Italian Futurism: Severini sets Futurist record (2008)','https://italianfuturism.org/?p=75']],vf:'V'},
{id:'russianavantgarde',n:'Russian avant-garde: Suprematism and Constructivism',from:1913,to:1932,place:'Moscow, Petrograd and Vitebsk',what:'Kazimir Malevich launched Suprematism, an art of pure geometric forms floating on white grounds, at the ’0.10’ exhibition in Petrograd in December 1915, where his Black Square hung across a corner like an icon. After the 1917 Revolution, Vladimir Tatlin, Alexander Rodchenko, Varvara Stepanova, Lyubov Popova and El Lissitzky developed Constructivism, rejecting easel painting for industrial materials, design, photography and propaganda in the service of the new state.',why:'Suprematism pushed abstraction to its limit, and Constructivism recast the artist as an engineer, shaping the Bauhaus, De Stijl, modern typography and graphic design. The Communist Party’s 1932 decree dissolving independent art groups, and the imposition of Socialist Realism, ended both.',look:'Look for floating rectangles, crosses and circles in flat colour on white (Suprematism), or diagonal compositions, photomontage, bold sans-serif type and red, black and white schemes (Constructivism).',artists:['Kazimir Malevich','Natalia Goncharova','Alexander Rodchenko','El Lissitzky','Lyubov Popova','Vladimir Tatlin','Ivan Kliun'],works:[{t:'Black Square',a:'Kazimir Malevich',y:'1915',where:'State Tretyakov Gallery, Moscow'},{t:'Suprematist Composition: White on White',a:'Kazimir Malevich',y:'1918',where:'Museum of Modern Art, New York'},{t:'Spatial Construction no. 12',a:'Alexander Rodchenko',y:'c. 1920',where:'Museum of Modern Art, New York'}],market:{state:'thin',note:'The finest Suprematist and Constructivist works are in museums, the field is notorious for forgeries, and Western houses have scaled back Russian-art sales since 2022, so well-provenanced pieces are rare and sell chiefly in New York and London. Malevich’s Suprematist Composition (1916) made $85.8m at Christie’s New York in May 2018, a record for any Russian work of art, while a 1930 Rodchenko maquette set his works-on-paper record at $1.5m at Christie’s New York in May 2026.',record:'Kazimir Malevich, Suprematist Composition (1916): $85.8m, Christie’s, New York, 15 May 2018',recordSrc:'https://www.artsy.net/article/artsy-editorial-malevich-suprematist-composition-sold-858-million-christies-breaking-record-work-russian-art'},links:['cubism','futurism','destijl','miriskusstva'],sources:[['Tate: Suprematism','https://www.tate.org.uk/art/art-terms/s/suprematism'],['Tate: Constructivism','https://www.tate.org.uk/art/art-terms/c/constructivism'],['Artsy: Malevich sets Russian art record (2018)','https://www.artsy.net/article/artsy-editorial-malevich-suprematist-composition-sold-858-million-christies-breaking-record-work-russian-art'],['Ocula: Christie’s $1.1bn New York night (May 2026)','https://ocula.com/magazine/art-news/christies-1bn-new-york-auction/']],vf:'V'},
{id:'dada',n:'Dada',from:1916,to:1924,place:'Zurich, Berlin, Paris and New York',what:'Dada began at the Cabaret Voltaire in Zurich in February 1916, founded by Hugo Ball and Emmy Hennings with Tristan Tzara, Jean (Hans) Arp, Marcel Janco and Richard Huelsenbeck, as a revolt against the First World War and the culture that produced it. It spread to Berlin, Cologne, Hanover, Paris and New York, using chance, nonsense poetry, collage, photomontage, performance and the readymade.',why:'Dada attacked the idea of art itself and moved value from craft to the artist’s choice, most famously in Marcel Duchamp’s Fountain (1917). Its readymades, photomontage and performance underpin Surrealism, Fluxus, Pop and Conceptual art.',look:'Look for found objects and readymades, collage and photomontage cut from mass media, chaotic typography, mechanical diagrams and deliberately absurd titles.',artists:['Marcel Duchamp','Man Ray','Francis Picabia','Kurt Schwitters','Hannah Höch','Jean (Hans) Arp','Max Ernst'],works:[{t:'Fountain',a:'Marcel Duchamp',y:'1917',where:'original lost; 1964 replica at Tate, London'},{t:'Cut with the Kitchen Knife Dada through the Last Weimar Beer-Belly Cultural Epoch of Germany',a:'Hannah Höch',y:'1919–20',where:'Nationalgalerie, Staatliche Museen zu Berlin'},{t:'Merzbild 25A (Das Sternenbild)',a:'Kurt Schwitters',y:'1920',where:'Kunstsammlung Nordrhein-Westfalen, Düsseldorf'}],market:{state:'thin',note:'Key Dada objects are few, fragile and mostly in museums, so the market runs on Picabia paintings, Schwitters collages, Arp reliefs, Man Ray photographs and authorised later editions of Duchamp’s readymades. These trade in Paris, London and New York to specialist collectors and institutions, and prices hinge on date, edition and provenance; top unique works are rarely at auction.'},links:['futurism','surrealism','conceptual'],sources:[['Tate: Dada','https://www.tate.org.uk/art/art-terms/d/dada'],['MoMA: Dada','https://www.moma.org/collection/terms/dada']],vf:'S'},
{id:'destijl',n:'De Stijl and the Bauhaus',from:1917,to:1933,place:'Netherlands; Weimar, Dessau and Berlin',what:'De Stijl (’The Style’) was founded in Leiden in 1917 by Theo van Doesburg with Piet Mondrian, Bart van der Leck and the architect J.J.P. Oud, and reduced art to straight lines, right angles, primary colours and black, white and grey. The Bauhaus, founded by Walter Gropius in Weimar in 1919, moved to Dessau in 1925 and Berlin in 1932 before closing under Nazi pressure in 1933, uniting art, craft and industry under teachers including Paul Klee, Wassily Kandinsky, László Moholy-Nagy and Josef Albers.',why:'Together they turned abstract form into a universal design language for architecture, furniture, typography and products. The Bauhaus diaspora after 1933, with Gropius and Marcel Breuer at Harvard, Mies van der Rohe in Chicago and Albers at Black Mountain College and Yale, spread modernist design across America.',look:'Look for asymmetric grids of black lines enclosing flat red, yellow and blue planes on white (De Stijl), and functional, machine-like forms, tubular steel and sans-serif type (Bauhaus).',artists:['Piet Mondrian','Paul Klee','Josef Albers','László Moholy-Nagy','Theo van Doesburg','Gerrit Rietveld','Marcel Breuer'],works:[{t:'Composition with Red, Blue and Yellow',a:'Piet Mondrian',y:'1930',where:'Kunsthaus Zürich'},{t:'Broadway Boogie Woogie',a:'Piet Mondrian',y:'1942–43',where:'Museum of Modern Art, New York'},{t:'Bauhaus Building, Dessau',a:'Walter Gropius',y:'1925–26',where:'in situ, Dessau'}],market:{state:'thin',note:'Mondrian’s classic grids are scarce and mostly institutional, so single sales set the level: Composition No. II (1930) made $51.0m at Sotheby’s New York in November 2022, just above the $50.6m paid for Composition No. III (1929) at Christie’s New York in 2015. Klee and Albers trade far more often at every price level, while Bauhaus and Rietveld furniture forms a separate design market in which early, documented examples carry a large premium over later production.',record:'Piet Mondrian, Composition No. II (1930): $51.0m, Sotheby’s, New York, 14 Nov 2022',recordSrc:'https://heni.com/news/article/piet-mondrian-composition-no-ii-2022-11-14'},links:['russianavantgarde','cubism','minimalism','artdeco'],sources:[['Tate: De Stijl','https://www.tate.org.uk/art/art-terms/d/de-stijl'],['Tate: Bauhaus','https://www.tate.org.uk/art/art-terms/b/bauhaus'],['Sotheby’s: Mondrian’s Composition No. II (2022)','https://www.sothebys.com/en/articles/an-extraordinary-example-of-piet-mondrians-groundbreaking-abstraction'],['HENI News: Mondrian auction record','https://heni.com/news/article/piet-mondrian-composition-no-ii-2022-11-14']],vf:'V'},
{id:'surrealism',n:'Surrealism',from:1924,to:1966,place:'Paris, then New York, Mexico City and beyond',what:'Surrealism was launched in Paris in 1924 with André Breton’s Manifesto of Surrealism, which drew on Freud to seek a ’superior reality’ in dreams, chance and the unconscious. Its artists either used automatic techniques to bypass conscious control (Joan Miró, André Masson, Max Ernst) or painted dream images with illusionistic precision (Salvador Dalí, René Magritte, Yves Tanguy).',why:'Surrealism was the most international avant-garde between the wars, reaching Belgium, Britain, Czechoslovakia, Japan, Mexico and the Caribbean. Its exiles in wartime New York passed automatism to the Abstract Expressionists.',look:'Look for incongruous juxtapositions, hyper-real dream spaces, hybrid creatures, biomorphic forms, automatic drawing and techniques such as frottage, decalcomania and collage.',artists:['René Magritte','Salvador Dalí','Joan Miró','Max Ernst','Leonora Carrington','Remedios Varo','Yves Tanguy'],works:[{t:'The Persistence of Memory',a:'Salvador Dalí',y:'1931',where:'Museum of Modern Art, New York'},{t:'The Treachery of Images',a:'René Magritte',y:'1929',where:'Los Angeles County Museum of Art'},{t:'The Harlequin’s Carnival',a:'Joan Miró',y:'1924–25',where:'Buffalo AKG Art Museum'}],market:{state:'heating',note:'Surrealism has been one of the strongest modern categories since its 2024 centenary, bought by American, European and Asian collectors, with fast-rising prices for women Surrealists. Magritte’s L’empire des lumières (1954) made $121.2m at Christie’s New York in November 2024, a record for the movement, and in May 2026 Miró’s Portrait de Madame K (1924) set his record at $53.5m and Remedios Varo a works-on-paper record at $4.5m.',record:'René Magritte, L’empire des lumières (1954): $121.2m, Christie’s, New York, 19 Nov 2024',recordSrc:'https://artdependence.com/articles/magritte-masterpiece-realizes-1212-million-new-record-for-surrealist-work-of-art/'},links:['dada','mexicanmuralism','abex','symbolism'],sources:[['Tate: Surrealism','https://www.tate.org.uk/art/art-terms/s/surrealism'],['MoMA: Surrealism','https://www.moma.org/collection/terms/surrealism'],['ArtDependence: Magritte sets Surrealist record (2024)','https://artdependence.com/articles/magritte-masterpiece-realizes-1212-million-new-record-for-surrealist-work-of-art/'],['Ocula: Christie’s $1.1bn New York night (May 2026)','https://ocula.com/magazine/art-news/christies-1bn-new-york-auction/']],vf:'V'},
{id:'artdeco',n:'Art Deco',from:1920,to:1939,place:'Paris, then worldwide',what:'Art Deco was the dominant decorative style of the 1920s and 1930s, named after the 1925 Exposition Internationale des Arts Décoratifs et Industriels Modernes in Paris. It combined luxury materials and craftsmanship with streamlined geometry drawn from Cubism, machines and ancient Egyptian and other non-Western sources, across architecture, furniture, jewellery, posters and painting.',why:'Art Deco was the first global modern style, shaping skyscrapers, cinemas, ocean liners and whole districts from New York and Miami to Mumbai and Shanghai. In painting, Tamara de Lempicka’s glossy, Cubist-inflected portraits became its emblem.',look:'Look for stepped and zigzag geometry, sunbursts, stylised streamlined figures, polished surfaces and materials such as lacquer, shagreen, ivory, chrome and exotic veneers.',artists:['Tamara de Lempicka','Jean Dunand','Émile-Jacques Ruhlmann','Eileen Gray','René Lalique','Jean-Michel Frank','A.M. Cassandre'],works:[{t:'Self-Portrait in the Green Bugatti',a:'Tamara de Lempicka',y:'1929',where:'private collection'},{t:'Chrysler Building',a:'William Van Alen',y:'1928–30',where:'in situ, New York'},{t:'Christ the Redeemer',a:'Paul Landowski',y:'1922–31',where:'in situ, Rio de Janeiro'}],market:{state:'steady',note:'The market splits between painting, led by Lempicka, and decorative arts, where signed furniture, lacquer and glass by Ruhlmann, Dunand, Gray and Lalique sell mainly in Paris and New York to collectors and designers. Lempicka’s Portrait de Marjorie Ferry (1932) made £16.3m ($21.1m) at Christie’s London in February 2020, 58% above the record she had set three months earlier.',record:'Tamara de Lempicka, Portrait de Marjorie Ferry (1932): $21.1m, Christie’s, London, 5 Feb 2020',recordSrc:'https://heni.com/news/article/tamara-de-lempicka-portrait-de-marjorie-ferry-2020-02-05'},links:['cubism','destijl','viennasecession'],sources:[['Tate: Art Deco','https://www.tate.org.uk/art/art-terms/a/art-deco'],['Britannica: Art Deco','https://www.britannica.com/art/Art-Deco'],['The Art Newspaper: Lempicka record at Christie’s (2020)','https://www.theartnewspaper.com/2020/02/06/and-all-that-jazz-upbeat-sale-at-christies-sees-tamara-de-lempicka-portrait-beat-record-set-just-three-months-ago'],['HENI News: Lempicka auction record','https://heni.com/news/article/tamara-de-lempicka-portrait-de-marjorie-ferry-2020-02-05']],vf:'V'},
{id:'mexicanmuralism',n:'Mexican muralism and Latin American modernism',from:1921,to:1970,place:'Mexico and Latin America',what:'After the Mexican Revolution the education minister José Vasconcelos commissioned murals for public buildings from 1921, and Diego Rivera, José Clemente Orozco and David Alfaro Siqueiros (’los tres grandes’) painted epic histories of Mexico’s indigenous past, revolution and labour. Across Latin America, modernists such as Frida Kahlo, Rufino Tamayo, Tarsila do Amaral, Joaquín Torres-García and Wifredo Lam built distinct idioms from local traditions and the European avant-garde.',why:'Muralism showed that modern art could be public, political and figurative, and it shaped the US New Deal mural programmes and young painters such as Jackson Pollock, who joined Siqueiros’s New York workshop in 1936. Latin American modernism overturned the idea that modern art flowed only outward from Paris.',look:'Look for monumental, simplified figures, pre-Columbian and folk motifs, revolutionary and labour subjects and, in easel painting, intense colour, symbolic self-portraiture or Constructivist grids (Torres-García).',artists:['Frida Kahlo','Diego Rivera','Rufino Tamayo','David Alfaro Siqueiros','José Clemente Orozco','Tarsila do Amaral','Joaquín Torres-García'],works:[{t:'Detroit Industry Murals',a:'Diego Rivera',y:'1932–33',where:'Detroit Institute of Arts'},{t:'The Two Fridas',a:'Frida Kahlo',y:'1939',where:'Museo de Arte Moderno, Mexico City'},{t:'Abaporu',a:'Tarsila do Amaral',y:'1928',where:'MALBA, Buenos Aires'}],market:{state:'heating',note:'Mexico has protected Kahlo’s work as national artistic heritage since 1984, so works inside the country cannot be exported and the few held abroad command trophy prices from American and Latin American collectors in New York. Her El sueño (La cama) (1940) made $54.7m at Sotheby’s New York in November 2025, a record for any woman artist, while Rivera’s The Rivals set a Latin American record of $9.8m from the Rockefeller collection in 2018.',record:'Frida Kahlo, El sueño (La cama) (1940): $54.7m, Sotheby’s, New York, 20 Nov 2025',recordSrc:'https://www.npr.org/2025/11/19/nx-s1-5584087/frida-kahlo-auction-record-sothebys-el-sueno-la-cama'},links:['surrealism','abex','harlemrenaissance'],sources:[['Whitney Museum: Vida Americana, Mexican muralists and US art','https://whitney.org/exhibitions/vida-americana'],['NPR: Kahlo sets record for a woman artist (2025)','https://www.npr.org/2025/11/19/nx-s1-5584087/frida-kahlo-auction-record-sothebys-el-sueno-la-cama'],['VOA: Rockefeller sale sets records (2018)','https://www.voanews.com/a/rockefeller-collection-record-auction/4390890.html']],vf:'V'},
{id:'harlemrenaissance',n:'Harlem Renaissance',from:1918,to:1937,place:'Harlem, New York',what:'The Harlem Renaissance was a flowering of Black literature, music and visual art centred on Harlem in New York from the end of the First World War to the mid-1930s, framed by Alain Locke’s 1925 anthology The New Negro. Painters, sculptors and photographers such as Aaron Douglas, Archibald Motley, Augusta Savage, Palmer Hayden and James Van Der Zee forged a modern Black image drawing on African art, jazz and urban life.',why:'It asserted Black Americans as authors and subjects of modern art at the height of segregation, and its workshops, notably Augusta Savage’s, trained the next generation, including Jacob Lawrence. Its project of self-representation runs through the Black figurative painting prominent in today’s market.',look:'Look for silhouetted, geometric figures with Art Deco and African motifs and concentric bands of light (Douglas), vivid nightlife scenes (Motley), and dignified studio portraits of the ’New Negro’.',artists:['Jacob Lawrence','Beauford Delaney','Archibald Motley','Aaron Douglas','Augusta Savage','Palmer Hayden','James Van Der Zee'],works:[{t:'Aspects of Negro Life: From Slavery Through Reconstruction',a:'Aaron Douglas',y:'1934',where:'Schomburg Center, New York Public Library'},{t:'Gamin',a:'Augusta Savage',y:'c. 1929',where:'Smithsonian American Art Museum, Washington'},{t:'The Migration Series',a:'Jacob Lawrence',y:'1940–41',where:'Phillips Collection, Washington, and Museum of Modern Art, New York'}],market:{state:'thin',note:'Few paintings of the 1920s and 1930s remain in private hands, so the market rests on specialist sales at Swann Galleries in New York and on evening-sale appearances by the generation trained in Harlem; an early Aaron Douglas woodcut proof made $100,000 at Swann in April 2024. Jacob Lawrence’s record is $6.2m for The Businessmen (1947) at Sotheby’s New York in 2018, and Beauford Delaney’s record rose 67% to $1.5m at Christie’s New York in November 2025.',record:'Jacob Lawrence, The Businessmen (1947): $6.2m, Sotheby’s, New York, 14 Nov 2018',recordSrc:'https://www.culturetype.com/2018/11/15/crushing-decade-old-auction-record-the-businessmen-by-jacob-lawrence-soars-to-6-1-million-placing-him-among-the-most-expensive-african-american-artists/'},links:['artdeco','mexicanmuralism','africanmodern'],sources:[['Britannica: Harlem Renaissance','https://www.britannica.com/event/Harlem-Renaissance-American-literature-and-art'],['The Met: The Harlem Renaissance and Transatlantic Modernism (2024)','https://www.metmuseum.org/exhibitions/harlem-renaissance-and-transatlantic-modernism'],['Culture Type: Jacob Lawrence record (2018)','https://www.culturetype.com/2018/11/15/crushing-decade-old-auction-record-the-businessmen-by-jacob-lawrence-soars-to-6-1-million-placing-him-among-the-most-expensive-african-american-artists/'],['HENI News: Beauford Delaney record (2025)','https://heni.com/news/article/beauford-delaney-the-sage-black-2025-11-17']],vf:'V'},
{id:'abex',n:'Abstract Expressionism',from:1943,to:1960,place:'New York',what:'Abstract Expressionism was the first American movement to gain international influence, developed in New York in the 1940s and 1950s by painters including Jackson Pollock, Willem de Kooning, Franz Kline, Lee Krasner and Joan Mitchell. Its ’action painters’ made gesture and process the subject, while its colour-field wing (Mark Rothko, Barnett Newman, Clyfford Still) sought the sublime through large expanses of colour.',why:'It moved the centre of the avant-garde from Paris to New York after the Second World War and made the huge, all-over canvas a standard modern format. Critics such as Clement Greenberg and Harold Rosenberg, and US cultural diplomacy, turned it into an emblem of post-war Western freedom.',look:'Look for large scale, all-over compositions without a single focal point, visible drips, pours and loaded brushstrokes, and emphasis on the physical act of painting.',artists:['Jackson Pollock','Willem de Kooning','Joan Mitchell','Franz Kline','Lee Krasner','Robert Motherwell','Clyfford Still'],works:[{t:'Autumn Rhythm (Number 30)',a:'Jackson Pollock',y:'1950',where:'Metropolitan Museum of Art, New York'},{t:'Woman I',a:'Willem de Kooning',y:'1950–52',where:'Museum of Modern Art, New York'},{t:'Number 7A, 1948',a:'Jackson Pollock',y:'1948',where:'private collection'}],market:{state:'heating',note:'Trophy post-war works reach the market mainly through estate sales in New York and are bought by American, European and Asian collectors, and Christie’s 20th- and 21st-century sales rose 79% to $2.3bn in the first half of 2026. Pollock’s Number 7A (1948), from the S.I. Newhouse collection, made $181.2m at Christie’s New York in May 2026, almost three times his previous record of $61.2m (Sotheby’s, 2021).',record:'Jackson Pollock, Number 7A, 1948: $181.2m, Christie’s, New York, 18 May 2026',recordSrc:'https://ocula.com/magazine/art-news/christies-1bn-new-york-auction/'},links:['surrealism','colorfield','cobra','gutai'],sources:[['Tate: Abstract Expressionism','https://www.tate.org.uk/art/art-terms/a/abstract-expressionism'],['MoMA: Abstract Expressionism','https://www.moma.org/collection/terms/abstract-expressionism'],['Ocula: Christie’s $1.1bn New York night (May 2026)','https://ocula.com/magazine/art-news/christies-1bn-new-york-auction/'],['USA Art News: Christie’s first half 2026','https://usaartnews.com/news/christies-reports-strongest-first-half-in-five-years-as-sales-jump-71/']],vf:'V'},
{id:'colorfield',n:'Colour Field and post-painterly abstraction',from:1949,to:1970,place:'New York and Washington',what:'Colour Field painting grew out of Abstract Expressionism in the late 1940s, when Mark Rothko, Barnett Newman and Clyfford Still began covering huge canvases with large flat or softly brushed areas of colour. From 1952 Helen Frankenthaler’s soak-stain technique led Morris Louis, Kenneth Noland and Jules Olitski to a cooler ’post-painterly abstraction’, named by Clement Greenberg in a 1964 exhibition in Los Angeles.',why:'It replaced gesture with colour as the main carrier of feeling, and made the flat, stained canvas itself a subject. It bridges Abstract Expressionism and Minimalism and shaped abstraction worldwide.',look:'Look for large fields of colour, stacked soft-edged rectangles (Rothko), vertical ’zips’ (Newman), thinned paint stained into raw canvas, and bare canvas used as part of the image.',artists:['Mark Rothko','Barnett Newman','Helen Frankenthaler','Clyfford Still','Morris Louis','Kenneth Noland','Sam Gilliam'],works:[{t:'Vir Heroicus Sublimis',a:'Barnett Newman',y:'1950–51',where:'Museum of Modern Art, New York'},{t:'Mountains and Sea',a:'Helen Frankenthaler',y:'1952',where:'Helen Frankenthaler Foundation, on loan to the National Gallery of Art, Washington'},{t:'Rothko Chapel paintings',a:'Mark Rothko',y:'1964–67',where:'Rothko Chapel, Houston'}],market:{state:'heating',note:'Rothko anchors the category at the top of New York evening sales, while Frankenthaler, Louis, Noland, Olitski and Gilliam form a deeper but much lower-priced tier bought by American and European collectors and museums. Rothko’s No. 15 (Two Greens and Red Stripe) (1964), bought from the artist by Agnes Gund in 1967, set his record at $98.4m at Christie’s New York in May 2026, 13% above the $86.9m paid for Orange, Red, Yellow in 2012.',record:'Mark Rothko, No. 15 (Two Greens and Red Stripe) (1964): $98.4m, Christie’s, New York, 18 May 2026',recordSrc:'https://heni.com/news/article/mark-rothko-no-15-two-greens-and-red-stripe-2026-05-18'},links:['abex','minimalism','dansaekhwa'],sources:[['Tate: Colour field painting','https://www.tate.org.uk/art/art-terms/c/colour-field-painting'],['Tate: Post-painterly abstraction','https://www.tate.org.uk/art/art-terms/p/post-painterly-abstraction'],['HENI News: Rothko auction record (May 2026)','https://heni.com/news/article/mark-rothko-no-15-two-greens-and-red-stripe-2026-05-18'],['Ocula: Christie’s $1.1bn New York night (May 2026)','https://ocula.com/magazine/art-news/christies-1bn-new-york-auction/']],vf:'V'},
{id:'gutai',n:'Gutai',from:1954,to:1972,place:'Ashiya and Osaka, Japan',what:'The Gutai Art Association was founded in 1954 in Ashiya, near Osaka, by the painter Jirō Yoshihara, who urged members to ’do what no one has done before’. Its artists, including Kazuo Shiraga, Atsuko Tanaka, Saburō Murakami, Shōzō Shimamoto and Sadamasa Motonaga, staged outdoor shows and performances, painting with their feet, bursting through paper screens and hurling bottles of paint.',why:'Gutai’s 1956 manifesto, about the encounter between body and matter, anticipated Happenings, performance and installation by several years. Through the critic Michel Tapié it linked post-war Japan with Art Informel and international abstraction; the group dissolved after Yoshihara’s death in 1972.',look:'Look for thick, swirling paint applied with the feet (Shiraga), torn or punctured surfaces, poured and dripped enamel, and the trace of a physical action fixed in the work.',artists:['Kazuo Shiraga','Atsuko Tanaka','Sadamasa Motonaga','Shōzō Shimamoto','Saburō Murakami','Jirō Yoshihara','Takesada Matsutani'],works:[{t:'Challenging Mud',a:'Kazuo Shiraga',y:'1955',where:'performance; known from photographs'},{t:'Electric Dress',a:'Atsuko Tanaka',y:'1956',where:'Takamatsu City Museum of Art (1986 remake)'},{t:'Passing Through',a:'Saburō Murakami',y:'1956',where:'performance; known from photographs'}],market:{state:'steady',note:'Gutai entered the international market after the Guggenheim’s 2013 survey, and Shiraga’s foot paintings, Tanaka’s circle paintings and Motonaga’s pours now sell in Hong Kong, New York and London to Asian, European and American buyers. Shiraga leads: Hoshōkai (Lop Nur) (1988) made $5.1m at Christie’s New York in May 2023, though below its upper estimate, and Japan’s art market slipped 1% in 2025 (Art Basel and UBS).'},links:['abex','cobra','monoha','superflat'],sources:[['Tate: Gutai','https://www.tate.org.uk/art/art-terms/g/gutai'],['Guggenheim: Gutai, Splendid Playground (2013)','https://www.guggenheim.org/exhibition/gutai-splendid-playground'],['HENI News: Kazuo Shiraga market (2023)','https://heni.com/news/article/avant-garde-artist-kazuo-shiragas-action-paintings-created-with-his-feet-are-in-demand'],['Art Basel and UBS report 2026 summary','https://macaubusiness.com/the-art-basel-and-ubs-global-art-market-report-2026-global-art-sales-rose-4-to-usd-59-6-billion-in-2025/']],vf:'V'},
{id:'cobra',n:'CoBrA and Art Informel / Tachisme',from:1945,to:1960,place:'Paris, Copenhagen, Brussels and Amsterdam',what:'In post-war Paris, ’Art Informel’ (formless art, a term promoted by the critic Michel Tapié from 1951) and ’Tachisme’ (from tache, stain) described the gestural abstraction of Jean Fautrier, Wols, Jean Dubuffet, Hans Hartung, Pierre Soulages, Georges Mathieu and Zao Wou-Ki. CoBrA, founded in Paris in 1948 by artists from Copenhagen, Brussels and Amsterdam, including Asger Jorn, Christian Dotremont, Karel Appel, Corneille and Constant, added spontaneous, brightly coloured figuration inspired by children’s drawings, folk art and myth before disbanding in 1951.',why:'These movements were Europe’s answer to Abstract Expressionism, putting matter, gesture and chance at the centre of painting after the trauma of war. CoBrA’s experimental spirit fed Jorn’s Situationist International and Constant’s New Babylon.',look:'Look for thick, worked surfaces, calligraphic or slashing gestures, black bars and sweeps over coloured grounds (Soulages, Hartung) and, in CoBrA, raw, brightly coloured creatures and faces painted with childlike directness.',artists:['Zao Wou-Ki','Pierre Soulages','Jean Dubuffet','Asger Jorn','Karel Appel','Hans Hartung','Corneille'],works:[{t:'Questioning Children',a:'Karel Appel',y:'1949',where:'Tate, London'},{t:'Letter to My Son',a:'Asger Jorn',y:'1956–57',where:'Tate, London'},{t:'Le Métafisyx',a:'Jean Dubuffet',y:'1950',where:'Centre Pompidou, Paris'}],market:{state:'steady',note:'CoBrA trades mainly in Copenhagen, Amsterdam and London to Northern European collectors at a fraction of American post-war prices: at Bruun Rasmussen in December 2022 Corneille set a record at €532,401, and works by Jorn and Appel made €372,680 and €293,900. The Paris abstractions reach higher levels, led by Zao Wou-Ki and Pierre Soulages, with Zao’s 21.04.59 making HK$105m ($13.3m) at Sotheby’s Hong Kong in October 2019.'},links:['abex','gutai','expressionism'],sources:[['Tate: CoBrA','https://www.tate.org.uk/art/art-terms/c/cobra'],['Tate: Art informel','https://www.tate.org.uk/art/art-terms/a/art-informel'],['Bruun Rasmussen: CoBrA results (Dec 2022)','https://mynewsdesk.com/bruun-rasmussen-auctioneers/pressreleases/art-with-a-bite-sold-for-dizzying-prices-at-bruun-rasmussen-3222354'],['Sotheby’s: Hong Kong autumn 2019 results','https://www.sothebys.com/en/articles/sothebys-hong-kong-2019-autumn-auctions-show-resilience-with-us426-million-sales?locale=en']],vf:'V'},
{id:'pop',n:'Pop Art',from:1956,to:1970,place:'London and New York',what:'Pop Art emerged in London in the mid-1950s with the Independent Group and Richard Hamilton, and in New York around 1961–62 with Andy Warhol, Roy Lichtenstein, Claes Oldenburg, James Rosenquist and Tom Wesselmann. It took its subjects and methods from advertising, comics, packaging, celebrity and mass production, often using commercial techniques such as silkscreen.',why:'Pop collapsed the boundary between fine art and consumer culture and made repetition, the multiple and the artist’s persona central to art. It underpins later appropriation art, Neo-Pop and Superflat.',look:'Look for flat, bright colour, Ben-Day dots, silkscreened photographs, repetition, enlarged consumer products and celebrity faces, and a cool, impersonal finish.',artists:['Andy Warhol','Roy Lichtenstein','David Hockney','Tom Wesselmann','Ed Ruscha','Claes Oldenburg','Richard Hamilton'],works:[{t:'Campbell’s Soup Cans',a:'Andy Warhol',y:'1962',where:'Museum of Modern Art, New York'},{t:'Whaam!',a:'Roy Lichtenstein',y:'1963',where:'Tate, London'},{t:'Just what is it that makes today’s homes so different, so appealing?',a:'Richard Hamilton',y:'1956',where:'Kunsthalle Tübingen'}],market:{state:'steady',note:'Pop is among the most liquid post-war categories, with Warhol, Lichtenstein and Hockney in most New York and London evening sales and prints forming a deep lower tier for a broad international buyer base. Warhol’s Shot Sage Blue Marilyn (1964) made $195m at Christie’s New York in May 2022, the record for an American work, Lichtenstein’s Anxious Girl (1964) fetched $46.1m there in May 2026, and David Hockney, whose record is about $90m (2018), died on 11 June 2026.',record:'Andy Warhol, Shot Sage Blue Marilyn (1964): $195.0m, Christie’s, New York, 9 May 2022',recordSrc:'https://www.npr.org/2022/05/09/1096617152/a-warhol-marilyn-brings-a-record-auction-price-195-million'},links:['dada','pictures','superflat','photorealism'],sources:[['Tate: Pop art','https://www.tate.org.uk/art/art-terms/p/pop-art'],['MoMA: Pop art','https://www.moma.org/collection/terms/pop-art'],['NPR: Warhol Marilyn makes $195m (2022)','https://www.npr.org/2022/05/09/1096617152/a-warhol-marilyn-brings-a-record-auction-price-195-million'],['ITV News: David Hockney dies (June 2026)','https://www.itv.com/news/2026-06-12/british-artist-david-hockney-dies-aged-88']],vf:'V'},
{id:'minimalism',n:'Minimalism',from:1959,to:1975,place:'New York',what:'Minimalism developed in New York in the early 1960s, when Donald Judd, Dan Flavin, Carl Andre, Robert Morris and Sol LeWitt made geometric, often serial objects from industrial materials such as steel, plywood, Plexiglas, firebricks and fluorescent tubes. Building on Frank Stella’s Black Paintings of 1959, they rejected illusion, composition and the artist’s hand in favour of what Judd called ’specific objects’ in real space.',why:'Minimalism shifted attention from the object to the viewer’s experience of space and light, opening the way to installation, Land Art and site-specific work. Its industrial fabrication and certificate-based works also changed how art is made, authenticated and sold.',look:'Look for simple geometric units, repetition and seriality, factory finishes, floor- or wall-based arrangements without plinths, and light or space used as material.',artists:['Donald Judd','Agnes Martin','Frank Stella','Dan Flavin','Carl Andre','Sol LeWitt','Robert Morris'],works:[{t:'Untitled (Stack)',a:'Donald Judd',y:'1967',where:'Museum of Modern Art, New York'},{t:'the nominal three (to William of Ockham)',a:'Dan Flavin',y:'1963',where:'Solomon R. Guggenheim Museum, New York'},{t:'Equivalent VIII',a:'Carl Andre',y:'1966',where:'Tate, London'}],market:{state:'steady',note:'Judd and Agnes Martin lead a narrow top tier bought by American and European collectors and museums, while certificate-based or editioned works by Flavin, Andre and LeWitt trade lower; Martin’s Grey Stone II made $18.7m at Sotheby’s New York in November 2023. In May 2026 a Judd stack made $12.8m at Christie’s, a record for the format, but works by LeWitt and Flavin sold below their low estimates to guarantors.',record:'Donald Judd, Untitled (DSS 42) (1963): $14.2m, Christie’s, New York, 2013',recordSrc:'https://www.masterworks.com/academy/posts/minimalism-why-less-commands-more-at-auction'},links:['colorfield','conceptual','destijl','monoha'],sources:[['Tate: Minimalism','https://www.tate.org.uk/art/art-terms/m/minimalism'],['MoMA: Minimalism','https://www.moma.org/collection/terms/minimalism'],['Masterworks Research: Minimalism at auction (June 2026)','https://www.masterworks.com/academy/posts/minimalism-why-less-commands-more-at-auction']],vf:'V'},
{id:'conceptual',n:'Conceptual Art and Fluxus',from:1962,to:1975,place:'New York, Germany and international',what:'Fluxus, organised by George Maciunas from 1962, was an international network including Yoko Ono, Nam June Paik, George Brecht, Joseph Beuys and Alison Knowles that made event scores, performances and cheap multiples. Conceptual art, defined in Sol LeWitt’s 1967 ’Paragraphs on Conceptual Art’, held that the idea is the work, using language, instructions, photographs and documents by artists such as Joseph Kosuth, Lawrence Weiner, On Kawara, John Baldessari and Hanne Darboven.',why:'Both dematerialised the art object and challenged the gallery system, making instruction, documentation and context central. Their legacy runs through installation, performance, institutional critique and the conceptualisms of Latin America, Eastern Europe and Asia.',look:'Look for text, instructions, certificates, typewritten documents and photographs, boxed multiples and scores, date paintings, and works that exist primarily as an idea or action.',artists:['Bruce Nauman','On Kawara','Joseph Beuys','John Baldessari','Yoko Ono','Nam June Paik','Joseph Kosuth'],works:[{t:'One and Three Chairs',a:'Joseph Kosuth',y:'1965',where:'Museum of Modern Art, New York'},{t:'Cut Piece',a:'Yoko Ono',y:'1964',where:'performance, first staged in Kyoto'},{t:'How to Explain Pictures to a Dead Hare',a:'Joseph Beuys',y:'1965',where:'performance, Galerie Schmela, Düsseldorf'}],market:{state:'thin',note:'Much of the work exists as instructions, documents, editions or performances, so auction supply is irregular and value depends on certificates and provenance. Demand concentrates on unique objects by Bruce Nauman, On Kawara’s date paintings, John Baldessari’s photo-paintings and Nam June Paik’s video sculptures, bought by museums and specialist collectors, while Fluxus multiples trade at modest levels, often in German and Italian sales.'},links:['dada','minimalism','arteprovera','pictures'],sources:[['Tate: Conceptual art','https://www.tate.org.uk/art/art-terms/c/conceptual-art'],['Tate: Fluxus','https://www.tate.org.uk/art/art-terms/f/fluxus']],vf:'S'},
{id:'arteprovera',n:'Arte Povera',from:1967,to:1972,place:'Turin, Rome, Genoa and Milan',what:'Arte Povera (’poor art’) was named by the critic Germano Celant for a 1967 exhibition in Genoa and gathered Italian artists including Michelangelo Pistoletto, Alighiero Boetti, Mario Merz, Jannis Kounellis, Giuseppe Penone, Pino Pascali, Luciano Fabro and Giovanni Anselmo. They used humble and organic materials such as earth, rags, wood, stone, fat, live animals and neon to set nature, memory and energy against consumer and technological culture.',why:'Arte Povera was Europe’s most influential response to Minimalism and Pop, bringing process, perishable materials and the body into sculpture and installation. It made Turin and Rome centres of the late-1960s avant-garde.',look:'Look for raw materials in tension or transformation, mirror paintings with photographic figures (Pistoletto), igloos and neon Fibonacci numbers (Merz), embroidered world maps (Boetti) and trees carved back to their growth rings (Penone).',artists:['Alighiero Boetti','Michelangelo Pistoletto','Pino Pascali','Jannis Kounellis','Mario Merz','Giuseppe Penone','Luciano Fabro'],works:[{t:'Venus of the Rags',a:'Michelangelo Pistoletto',y:'1967 (remade 1974)',where:'Tate, London'},{t:'Untitled (12 Horses)',a:'Jannis Kounellis',y:'1969',where:'installation, Galleria L’Attico, Rome'},{t:'Igloo di Giap',a:'Mario Merz',y:'1968',where:'Centre Pompidou, Paris'}],market:{state:'steady',note:'Prices are set largely in London’s October Italian sales and in Milan, with buyers in Italy, the rest of Europe and the United States; Artprice reported in 2024 that the top end had cooled since 2014, when Arte Povera artists turned over about $106m at auction. Boetti leads with a record of about $8.8m (2022), ahead of Pistoletto ($4.8m, 2017), Pascali ($3.3m, 2016) and Kounellis ($2m, 2014).'},links:['minimalism','conceptual','monoha'],sources:[['Tate: Arte Povera','https://www.tate.org.uk/art/art-terms/a/arte-povera'],['MoMA: Arte Povera','https://www.moma.org/collection/terms/arte-povera'],['Artprice: Is Arte Povera less valuable than before? (2024)','https://it.artprice.com/artmarketinsight/is-arte-povera-less-valuable-than-before'],['The Art Newspaper: Pascali record (2016)','https://www.theartnewspaper.com/2016/10/07/record-for-pino-pascali-at-christies-italian-sale']],vf:'V'},
{id:'monoha',n:'Mono-ha',from:1968,to:1975,place:'Tokyo',what:'Mono-ha (’School of Things’) was a loose group of artists in Tokyo from about 1968 to the mid-1970s, including Lee Ufan, Nobuo Sekine, Kishio Suga, Koji Enokura and Susumu Koshimizu. They arranged largely unaltered natural and industrial materials such as stone, wood, steel plate, glass, paper and earth to reveal relationships between objects, space and perception rather than to make images.',why:'Mono-ha broke with Western-style object-making in Japan and became an Asian counterpart to Arte Povera and post-Minimalism. Its starting point is usually given as Sekine’s Phase—Mother Earth (1968), an earth cylinder beside the hole it came from in Kobe’s Suma Rikyu Park.',look:'Look for raw stones resting on glass or steel, materials held in tension or balance, minimal intervention, and temporary arrangements that survive as remakes and photographs.',artists:['Lee Ufan','Nobuo Sekine','Kishio Suga','Koji Enokura','Susumu Koshimizu','Katsuro Yoshida','Jiro Takamatsu'],works:[{t:'Phase—Mother Earth',a:'Nobuo Sekine',y:'1968',where:'temporary work, Suma Rikyu Park, Kobe; known from photographs'},{t:'Relatum series',a:'Lee Ufan',y:'1968 onwards',where:'Lee Ufan Museum, Naoshima, among others'},{t:'Law of Situation',a:'Kishio Suga',y:'1971',where:'temporary installation, remade for exhibitions'}],market:{state:'thin',note:'Lee Ufan accounts for almost all Mono-ha value at auction: in 2013 Artprice found he held the movement’s top 114 prices while most other Mono-ha works sold for a few thousand dollars, and his works made $54.1m at auction in the two years to mid-2023. His sales run mainly through Seoul, Hong Kong and New York, with highs such as $2.66m for East Winds (1984) at Seoul Auction in 2021, while Sekine, Suga and Enokura appear rarely.'},links:['arteprovera','minimalism','dansaekhwa','gutai'],sources:[['Tate: Mono-ha','https://www.tate.org.uk/art/art-terms/m/mono-ha'],['Guggenheim: Lee Ufan, Marking Infinity (2011)','https://www.guggenheim.org/exhibition/lee-ufan-marking-infinity'],['Artprice: Top 10 Mono-ha (2013)','https://www.artprice.com/artmarketinsight/top-10-mono-ha'],['HENI News: Lee Ufan market (2023)','https://heni.com/news/article/lee-ufan-avant-garde-korean-artist-gets-major-museum-show-in-japan']],vf:'V'},
{id:'dansaekhwa',n:'Dansaekhwa',from:1970,to:1980,place:'Seoul',what:'Dansaekhwa (’monochrome painting’) describes Korean abstraction of the 1970s by Park Seo-bo, Ha Chong-hyun, Yun Hyong-keun, Chung Sang-hwa, Lee Ufan and Kwon Young-woo, framed by shows such as ’Five Korean Artists, Five Kinds of White’ at Tokyo Gallery in 1975. Through repetitive, labour-intensive processes, such as pencil lines drawn into wet paint, oil pushed through hemp, and layered and peeled surfaces, they made restrained fields of near-monochrome colour.',why:'Under the Park Chung-hee dictatorship it offered a meditative abstraction rooted in materials such as hanji paper and hemp, distinct from Western Minimalism. Its revival from 2014 put Korean modernism into international museums and salerooms.',look:'Look for near-monochrome surfaces in white, beige, umber or blue built up by repetition: scored pencil lines (Park), paint pushed through hemp from the back (Ha), bleeding umber bars (Yun) and grids of flaking paint (Chung).',artists:['Park Seo-bo','Lee Ufan','Ha Chong-hyun','Yun Hyong-keun','Chung Sang-hwa','Kwon Young-woo','Chung Chang-sup'],works:[{t:'Ecriture (Myobop) series',a:'Park Seo-bo',y:'1967 onwards',where:'National Museum of Modern and Contemporary Art, Korea, among others'},{t:'Conjunction series',a:'Ha Chong-hyun',y:'1974 onwards',where:'National Museum of Modern and Contemporary Art, Korea, among others'},{t:'Umber-Blue series',a:'Yun Hyong-keun',y:'1973 onwards',where:'National Museum of Modern and Contemporary Art, Korea, among others'}],market:{state:'steady',note:'Dansaekhwa boomed from 2014, after exhibitions at Kukje Gallery in Seoul and Blum & Poe in Los Angeles, and Park Seo-bo passed $1m at auction in 2015 and reached about $1.7m in Hong Kong by 2018 (Artprice). It trades mainly through Seoul Auction, K-Auction and Hong Kong to Korean and wider Asian buyers, and South Korea’s art market grew 6% in 2025 (Art Basel and UBS), but the Korean auction record belongs to the precursor Kim Whanki, whose Universe (1971) made HK$88m (₩13.2bn) at Christie’s Hong Kong in 2019.'},links:['monoha','minimalism','colorfield'],sources:[['Korea JoongAng Daily: How Dansaekhwa took over (2026)','https://www.koreajoongangdaily.com/lifestyle/dansaekhwa-has-taken-over-the-modern-art-world-but-the-story-of-how-that-happened-is-up-for-debate/12715638'],['Artprice: Top results in Korea (2018)','https://www.artprice.com/artmarketinsight/top-results-in-korea'],['Korea Times: Kim Whanki’s Universe record (2019)','https://www.koreatimes.co.kr/amp/lifestyle/travel-food/20191125/w132-billion-kim-whan-kis-universe-makes-history']],vf:'V'},
{id:'photorealism',n:'Photorealism',from:1967,to:1980,place:'New York and California',what:'Photorealism emerged in the United States in the late 1960s, when painters such as Richard Estes, Chuck Close, Robert Bechtle, Ralph Goings, Audrey Flack and Malcolm Morley began transferring photographs onto canvas with meticulous, often airbrushed precision. Named by the dealer Louis K. Meisel around 1969 and showcased at Documenta 5 in 1972, it took ordinary American motifs such as storefronts, cars, diners, suburban houses and faces.',why:'Photorealism reasserted painting and figuration against Minimalism and Conceptual art while making the camera’s way of seeing its real subject. It ran parallel to Gerhard Richter’s photo-paintings and anticipated later art built from photographic and digital images.',look:'Look for crisp, even focus across the whole picture, reflections in glass and chrome, grid-transferred faces at monumental scale, and a deadpan, camera-like neutrality.',artists:['Chuck Close','Richard Estes','Malcolm Morley','Audrey Flack','Robert Bechtle','Ralph Goings','Duane Hanson'],works:[{t:'Big Self-Portrait',a:'Chuck Close',y:'1967–68',where:'Walker Art Center, Minneapolis'},{t:'Telephone Booths',a:'Richard Estes',y:'1967',where:'Museo Nacional Thyssen-Bornemisza, Madrid'},{t:'Marilyn (Vanitas)',a:'Audrey Flack',y:'1977',where:'University of Arizona Museum of Art, Tucson'}],market:{state:'thin',note:'Photorealist paintings take months to make, so supply is small and the market is specialist, centred on New York dealers and occasional appearances in American day and evening sales. Prices have stayed well below those of Pop and Minimalism, with demand mainly from American collectors and museums.'},links:['pop','pictures','minimalism'],sources:[['Tate: Photorealism','https://www.tate.org.uk/art/art-terms/p/photorealism'],['Walker Art Center: Chuck Close, Big Self-Portrait','https://walkerart.org/collections/artworks/big-self-portrait']],vf:'S'},
{id:'neoexpressionism',n:'Neo-Expressionism and 1980s New York',from:1978,to:1989,place:'New York, Germany and Italy',what:'Neo-Expressionism was the return of large, figurative, emotionally charged painting around 1978–80, led in Germany by Georg Baselitz, Anselm Kiefer, A.R. Penck and Jörg Immendorff, in Italy by the Transavanguardia (Sandro Chia, Francesco Clemente, Enzo Cucchi) and in the United States by Julian Schnabel and David Salle. In downtown New York it overlapped with graffiti and the East Village scene, where Jean-Michel Basquiat moved from SAMO© street tags to canvases mixing text, anatomy, Black history and art history.',why:'It ended the dominance of Minimal and Conceptual art and fuelled the booming 1980s gallery market in SoHo and the East Village. Basquiat, who died in 1988 aged 27, became the decade’s defining figure and an anchor of today’s contemporary auction market.',look:'Look for raw, expressive brushwork at large scale, crude or crowned figures, crossed-out words and lists, collage, and references to myth, history and the street.',artists:['Jean-Michel Basquiat','Keith Haring','Anselm Kiefer','Georg Baselitz','Julian Schnabel','Francesco Clemente','David Salle'],works:[{t:'Untitled (Skull)',a:'Jean-Michel Basquiat',y:'1981',where:'The Broad, Los Angeles'},{t:'Untitled',a:'Jean-Michel Basquiat',y:'1982',where:'private collection'},{t:'Margarethe',a:'Anselm Kiefer',y:'1981',where:'San Francisco Museum of Modern Art'}],market:{state:'cooling',note:'Basquiat is the engine of the category, traded each season in New York, London and Hong Kong to American, European and Asian buyers, while German and Italian Neo-Expressionists sell at a fraction of his level. His record is $110.5m for Untitled (1982), bought by Yusaku Maezawa at Sotheby’s New York in May 2017, but the wider contemporary market has corrected, with New York auction sales of contemporary art down 15.2% in 2025 to their lowest level since 2020 (Bank of America and ArtTactic).',record:'Jean-Michel Basquiat, Untitled (1982): $110.5m, Sotheby’s, New York, 18 May 2017',recordSrc:'https://www.theartnewspaper.com/2017/05/18/basquiat-skull-painting-sells-for-record-dollar1105m-at-sothebys'},links:['expressionism','streetart','pictures','pop'],sources:[['Tate: Neo-expressionism','https://www.tate.org.uk/art/art-terms/n/neo-expressionism'],['The Art Newspaper: Basquiat record (2017)','https://www.theartnewspaper.com/2017/05/18/basquiat-skull-painting-sells-for-record-dollar1105m-at-sothebys'],['Bank of America and ArtTactic: 2026 US Art Market Report','https://mlaem.fs.ml.com/content/dam/ust/articles/pdf/US-Art-Market-Report.pdf']],vf:'V'},
{id:'pictures',n:'Pictures Generation and appropriation',from:1977,to:1989,place:'New York',what:'The Pictures Generation takes its name from ’Pictures’, a 1977 exhibition at Artists Space in New York organised by the critic Douglas Crimp, and describes artists such as Cindy Sherman, Richard Prince, Barbara Kruger, Sherrie Levine, Louise Lawler, Robert Longo and Jack Goldstein. Raised on television, film and advertising, they re-photographed, cropped and restaged mass-media images to expose how pictures shape identity, desire and power.',why:'Their appropriation challenged originality and authorship and made photography central to contemporary art. Their methods anticipate today’s image culture of remix and social media, and Prince’s re-photographed images became test cases in copyright law.',look:'Look for re-photographed adverts and film stills, staged self-portraits in roles, bold red, white and black text over found photographs (Kruger), and copies of famous works presented as new work (Levine).',artists:['Cindy Sherman','Richard Prince','Barbara Kruger','Robert Longo','Sherrie Levine','Louise Lawler','Jack Goldstein'],works:[{t:'Untitled Film Stills',a:'Cindy Sherman',y:'1977–80',where:'Museum of Modern Art, New York'},{t:'Untitled (Cowboy)',a:'Richard Prince',y:'1989',where:'Metropolitan Museum of Art, New York'},{t:'Untitled (Your body is a battleground)',a:'Barbara Kruger',y:'1989',where:'The Broad, Los Angeles'}],market:{state:'steady',note:'Supply is dominated by editioned photographs, so prices depend on edition size, print date and condition, and trading is concentrated in New York and London. The most sought-after pieces are Sherman’s early vintage prints, Prince’s joke and nurse paintings and Kruger’s unique works, bought by American and European collectors and museums.'},links:['pop','conceptual','neoexpressionism','digital'],sources:[['Tate: Pictures Generation','https://www.tate.org.uk/art/art-terms/p/pictures-generation'],['Tate: Appropriation','https://www.tate.org.uk/art/art-terms/a/appropriation']],vf:'S'},
{id:'yba',n:'Young British Artists',from:1988,to:2000,place:'London',what:'The Young British Artists emerged from Goldsmiths College in London with ’Freeze’, a 1988 warehouse exhibition in Docklands organised by Damien Hirst, and were promoted by the collector Charles Saatchi. Artists including Hirst, Tracey Emin, Sarah Lucas, Rachel Whiteread, Chris Ofili, Marc Quinn, Gary Hume and Jenny Saville made provocative, media-savvy work from animals in formaldehyde, unmade beds, casts and elephant dung.',why:'The YBAs made London a global centre for contemporary art and helped create the climate for Tate Modern (2000) and Frieze Art Fair (2003). ’Sensation’, the 1997 show of Saatchi’s collection at the Royal Academy, made them household names.',look:'Look for provocative materials and titles, vitrines and preserved animals, spot and spin paintings, confessional text and neon (Emin), casts of negative space (Whiteread), and a frankly entrepreneurial approach to production.',artists:['Damien Hirst','Jenny Saville','Tracey Emin','Chris Ofili','Rachel Whiteread','Sarah Lucas','Marc Quinn'],works:[{t:'The Physical Impossibility of Death in the Mind of Someone Living',a:'Damien Hirst',y:'1991',where:'private collection'},{t:'My Bed',a:'Tracey Emin',y:'1998',where:'private collection, on long-term loan to Tate'},{t:'House',a:'Rachel Whiteread',y:'1993',where:'demolished 1994, London'}],market:{state:'cooling',note:'The YBA market peaked in 2007–08, when Hirst’s Lullaby Spring (2002) made £9.6m ($19.1m) at Sotheby’s London in June 2007 and he sold new work directly through Sotheby’s in September 2008. It now trades mainly in London, with demand concentrated on the strongest early pieces and on painters such as Jenny Saville rather than on studio-produced series.',record:'Damien Hirst, Lullaby Spring (2002): $19.1m, Sotheby’s, London, 21 Jun 2007',recordSrc:'https://mg.co.za/article/2007-06-22-hirst-most-expensive-living-artist-in-record-week'},links:['conceptual','pop','neoexpressionism','streetart'],sources:[['Tate: Young British Artists (YBAs)','https://www.tate.org.uk/art/art-terms/y/young-british-artists-ybas'],['Mail & Guardian: Hirst sets living-artist record (2007)','https://mg.co.za/article/2007-06-22-hirst-most-expensive-living-artist-in-record-week']],vf:'V'},
{id:'chinesecontemporary',n:'Chinese contemporary art',from:1985,to:null,place:'Beijing, Shanghai and Hong Kong',what:'Chinese contemporary art grew from the ’85 New Wave, when groups across China absorbed Western modernism after the Cultural Revolution, culminating in the ’China/Avant-Garde’ exhibition at the National Art Museum in Beijing in February 1989. After Tiananmen, Political Pop (Wang Guangyi), Cynical Realism (Fang Lijun, Yue Minjun), Zhang Xiaogang’s Bloodline portraits and Zeng Fanzhi’s Mask series found Western collectors, followed by Ai Weiwei, Xu Bing, Cai Guo-Qiang and younger painters such as Liu Ye.',why:'It gave the world a visual language for China’s transformation and helped make Beijing, Shanghai and Hong Kong major art-market centres. Its auction boom of the mid-2000s, led by Sotheby’s and Christie’s in Hong Kong, was one of the first speculative surges in contemporary art.',look:'Look for ironic propaganda and consumer imagery (Political Pop), grinning or yawning self-caricatures, sepia family portraits linked by red lines, masked figures, and invented or deconstructed Chinese characters.',artists:['Zeng Fanzhi','Zhang Xiaogang','Liu Ye','Yue Minjun','Wang Guangyi','Ai Weiwei','Xu Bing'],works:[{t:'The Last Supper',a:'Zeng Fanzhi',y:'2001',where:'private collection'},{t:'Bloodline: Big Family No. 3',a:'Zhang Xiaogang',y:'1995',where:'private collection'},{t:'Sunflower Seeds',a:'Ai Weiwei',y:'2010',where:'Tate, London'}],market:{state:'cooling',note:'The market centres on Hong Kong and on mainland houses such as Poly and China Guardian, with mainly Asian buyers, and China’s art market grew only about 1% in 2025 to $8.5bn, 14% of global sales (Art Basel and UBS). Zeng Fanzhi’s The Last Supper (2001) set the Asian contemporary record at $23.3m at Sotheby’s Hong Kong in October 2013, and recent strength is selective, such as a Liu Ye canvas sold for $3.8m at Art Basel Hong Kong in 2026.',record:'Zeng Fanzhi, The Last Supper (2001): $23.3m, Sotheby’s, Hong Kong, 5 Oct 2013',recordSrc:'https://edition.cnn.com/2013/10/06/business/record-asian-art/index.html'},links:['pop','chineseink','superflat','neoexpressionism'],sources:[['Guggenheim: Art and China after 1989','https://www.guggenheim.org/exhibition/art-and-china-after-1989-theater-of-the-world'],['CNN: Zeng Fanzhi sets Asian contemporary record (2013)','https://edition.cnn.com/2013/10/06/business/record-asian-art/index.html'],['Art Basel and UBS report 2026 summary','https://macaubusiness.com/the-art-basel-and-ubs-global-art-market-report-2026-global-art-sales-rose-4-to-usd-59-6-billion-in-2025/'],['Iga Fencu: Under the hammer (July 2026)','https://www.igafencu.com/articles/under-the-hammer-july-2026']],vf:'V'},
{id:'indianmodern',n:'Progressive Artists’ Group and Indian modernism',from:1947,to:1990,place:'Bombay (Mumbai), Delhi, Paris and London',what:'The Progressive Artists’ Group was founded in Bombay in December 1947, months after Independence, by F.N. Souza with S.H. Raza, M.F. Husain, K.H. Ara, H.A. Gade and S.K. Bakre, and later drew in V.S. Gaitonde, Tyeb Mehta, Akbar Padamsee and Krishen Khanna. They rejected both academic realism and the nationalist Bengal School, fusing European modernism, from Expressionism and Cubism to abstraction, with Indian subjects, colour and philosophy.',why:'They defined a secular, cosmopolitan modern art for the new republic, building on pioneers such as Amrita Sher-Gil. Their work now anchors South Asian art at auction and in collections from the Kiran Nadar Museum of Art in Delhi to Tate.',look:'Look for bold distorted figures and heavy black outlines (Souza), horses and village scenes in planar colour (Husain), the bindu circle and hot geometric colour (Raza), luminous layered abstraction (Gaitonde) and split figures and diagonals (Tyeb Mehta).',artists:['M.F. Husain','V.S. Gaitonde','S.H. Raza','Tyeb Mehta','F.N. Souza','Amrita Sher-Gil','Akbar Padamsee'],works:[{t:'Untitled (Gram Yatra)',a:'M.F. Husain',y:'1954',where:'private collection'},{t:'Crucifixion',a:'F.N. Souza',y:'1959',where:'Tate, London'},{t:'Saurashtra',a:'S.H. Raza',y:'1983',where:'private collection'}],market:{state:'heating',note:'Indian modern art is one of the few segments still setting records, driven by Indian and diaspora collectors buying at Saffronart, AstaGuru and Pundole’s in Mumbai and at Christie’s and Sotheby’s in New York and London. M.F. Husain’s Untitled (Gram Yatra) (1954) made $13.8m at Christie’s New York in March 2025, almost double Amrita Sher-Gil’s $7.4m record of 2023, and in April 2026 Saffronart sold Raja Ravi Varma’s 19th-century Yashoda and Krishna for Rs 167.2 crore ($18.0m), a record for any Indian work.',record:'M.F. Husain, Untitled (Gram Yatra) (1954): $13.8m, Christie’s, New York, 19 Mar 2025',recordSrc:'https://www.theweek.in/wire-updates/national/2025/03/20/lst1-art-husain-record.html'},links:['expressionism','cubism','africanmodern','academic'],sources:[['The Art Newspaper: Husain record at Christie’s (2025)','https://theartnewspaper.com/2025/03/19/record-mf-husain-indian-painting-christies-auction'],['The Week: Husain becomes most expensive modern Indian work (2025)','https://www.theweek.in/wire-updates/national/2025/03/20/lst1-art-husain-record.html'],['Times of Oman: Ravi Varma sets Indian record (2026)','https://timesofoman.com/article/170235-raja-ravi-varmas-painting-yashoda-and-krishna-sets-indian-art-record-with-rs-1672-crore-sale-in-auction']],vf:'V'},
{id:'africanmodern',n:'African modernism and contemporary African art',from:1950,to:null,place:'Lagos, Zaria, Khartoum, Dakar, Johannesburg and the diaspora',what:'African modernism took shape around independence from the 1950s in centres such as the Zaria Art Society and Mbari Club in Nigeria, the Khartoum School in Sudan and the École de Dakar, alongside earlier figures such as Ben Enwonwu and Irma Stern. Artists such as Uche Okeke, Ibrahim El-Salahi, Skunder Boghossian, Gerard Sekoto and Ernest Mancoba fused local forms, scripts and myths with international modernism, and since the 1990s El Anatsui, William Kentridge, Yinka Shonibare and Njideka Akunyili Crosby have made African art central to global contemporary art.',why:'Its ’natural synthesis’ (Uche Okeke’s term) of local and modern traditions rejected the idea that modernism was a Western export. Okwui Enwezor’s exhibitions and the growth of fairs and biennials in Lagos, Johannesburg, Dakar and Marrakech built the institutional and market infrastructure.',look:'Look for uli line drawing (Nsukka), Arabic calligraphy fused with figuration (El-Salahi), elegant elongated figures (Enwonwu), bottle-top and metal tapestries (El Anatsui), Dutch wax-print fabric (Shonibare) and layered photo-transfer interiors (Akunyili Crosby).',artists:['El Anatsui','Ben Enwonwu','Irma Stern','Ibrahim El-Salahi','Njideka Akunyili Crosby','William Kentridge','Amoako Boafo'],works:[{t:'Tutu',a:'Ben Enwonwu',y:'1974',where:'private collection'},{t:'Reborn Sounds of Childhood Dreams I',a:'Ibrahim El-Salahi',y:'1961–65',where:'Tate, London'},{t:'Gravity and Grace',a:'El Anatsui',y:'2010',where:'Brooklyn Museum, New York'}],market:{state:'cooling',note:'Modernists sell mainly at Bonhams, Sotheby’s and Strauss & Co in London and Johannesburg, with Nigerian, South African and diaspora buyers prominent; Ben Enwonwu’s Tutu (1974) made £1.2m at Bonhams London in February 2018, then a record for Nigerian art. The contemporary side has cooled since the 2021–22 rush for young West African figurative painters, and at Sotheby’s London in September 2024 four of ten featured African lots went unsold.'},links:['harlemrenaissance','indianmodern','ultracontemporary'],sources:[['Morocco World News: Enwonwu’s Tutu sets record (2018)','https://www.moroccoworldnews.com/2018/03/91819/african-mona-lisa-fetches-record-breaking-price-at-london-auction/'],['The African Mirror: Sotheby’s African sale (2024)','https://theafricanmirror.africa/news/the-10-most-expensive-african-artworks-at-a-major-international-art-auction/']],vf:'V'},
{id:'streetart',n:'Graffiti and street art',from:1970,to:null,place:'New York, then London, Bristol, Paris and worldwide',what:'Graffiti writing grew on New York subway trains in the early 1970s, and by about 1980 artists including Jean-Michel Basquiat, Keith Haring, Lee Quiñones, Lady Pink and Futura brought it into galleries. From the 1990s ’street art’ widened into stencils, posters, stickers and murals, led by Banksy from Bristol, Shepard Fairey, Invader and JR, and by KAWS, whose cartoon characters crossed from the street into toys and sculpture.',why:'It turned public space into a gallery and built careers outside the institutions through anonymity, humour and political messaging. Banksy’s stunts and Fairey’s 2008 Obama ’Hope’ poster showed how street imagery could dominate mass media.',look:'Look for spray-paint and stencil techniques, wheatpaste posters, tags and lettering, satirical slogans and recurring characters, and for official authentication, such as Banksy’s Pest Control certificates.',artists:['Banksy','KAWS','Keith Haring','Shepard Fairey','Invader','JR','Futura'],works:[{t:'Love is in the Bin',a:'Banksy',y:'2018',where:'private collection'},{t:'Crack Is Wack',a:'Keith Haring',y:'1986',where:'in situ, Harlem River Drive, New York'},{t:'Barack Obama (’Hope’)',a:'Shepard Fairey',y:'2008',where:'National Portrait Gallery, Washington'}],market:{state:'cooling',note:'Banksy dominates, backed by a deep market in prints authenticated by his Pest Control office and bought by younger and online buyers, alongside KAWS, Haring and Fairey, mainly through London, New York and Hong Kong sales. His record is £18.6m ($25.4m) for Love is in the Bin, the canvas he shredded at Sotheby’s in 2018, resold at Sotheby’s London in October 2021, a year after Game Changer made £16.7m ($23.1m).',record:'Banksy, Love is in the Bin (2018): $25.4m, Sotheby’s, London, 14 Oct 2021',recordSrc:'https://artfixdaily.com/news_feed/2021/10/14/8891-banksys-shredded-painting-sells-for-artist-record-of-254-million'},links:['neoexpressionism','pop','yba','digital'],sources:[['Tate: Street art','https://www.tate.org.uk/art/art-terms/s/street-art'],['Tate: Graffiti art','https://www.tate.org.uk/art/art-terms/g/graffiti-art'],['Artfix Daily: Banksy record at Sotheby’s (2021)','https://artfixdaily.com/news_feed/2021/10/14/8891-banksys-shredded-painting-sells-for-artist-record-of-254-million']],vf:'V'},
{id:'digital',n:'Digital and NFT art',from:1965,to:null,place:'International and online',what:'Digital art began in the 1960s with plotter drawings by Frieder Nake, Georg Nees, Vera Molnár and A. Michael Noll, and grew through computer graphics, net art and generative software. From 2017 non-fungible tokens (NFTs) on blockchains such as Ethereum let unique or limited digital works be owned, traded and authenticated online, and a speculative boom in 2021 brought them into the major auction houses.',why:'NFTs gave digital art a native system of ownership, provenance and resale royalties and brought crypto-wealthy collectors into the market. The 2022 crypto crash exposed the speculation, but generative and AI-driven work has kept a place in museums and salerooms.',look:'Look for generative code and algorithmic variation, pixel and 3D-rendered imagery, on-chain metadata and provenance, editions minted on Ethereum or Tezos, and screen-based or hybrid physical-digital works.',artists:['Beeple','Tyler Hobbs','Larva Labs (CryptoPunks)','Refik Anadol','Vera Molnár','Dmitri Cherniak','XCOPY'],works:[{t:'Everydays: The First 5000 Days',a:'Beeple',y:'2007–21',where:'private collection'},{t:'CryptoPunks',a:'Larva Labs',y:'2017',where:'10,000 tokens; examples at LACMA, Los Angeles, and Centre Pompidou, Paris'},{t:'Fidenza',a:'Tyler Hobbs',y:'2021',where:'999 outputs on Art Blocks; private collections'}],market:{state:'thin',note:'Beeple’s Everydays: The First 5000 Days made $69.3m in a Christie’s online sale in March 2021, the first standalone NFT offered by a major auction house and then the third-highest auction price for a living artist. After the 2022 crypto crash NFT trading shrank to a small specialist market, and online art sales overall fell to $9.2bn in 2025, their lowest level since 2019 (Art Basel and UBS).',record:'Beeple, Everydays: The First 5000 Days: $69.3m, Christie’s, online sale, 11 Mar 2021',recordSrc:'https://www.theartnewspaper.com/2021/03/11/wtaf-beeple-nft-work-sells-for-astonishing-dollar693m-at-christies-after-flurry-of-last-minute-bids-nearly-crashes-website'},links:['conceptual','pictures','streetart','ultracontemporary'],sources:[['Tate: Digital art','https://www.tate.org.uk/art/art-terms/d/digital-art'],['The Art Newspaper: Beeple NFT makes $69.3m (2021)','https://www.theartnewspaper.com/2021/03/11/wtaf-beeple-nft-work-sells-for-astonishing-dollar693m-at-christies-after-flurry-of-last-minute-bids-nearly-crashes-website'],['Art Basel and UBS report 2026 summary','https://macaubusiness.com/the-art-basel-and-ubs-global-art-market-report-2026-global-art-sales-rose-4-to-usd-59-6-billion-in-2025/']],vf:'V'},
{id:'ultracontemporary',n:'Ultra-contemporary painting',from:2015,to:null,place:'London, New York, Los Angeles and Hong Kong',what:'Ultra-contemporary is a market category rather than a style: work by artists born after about 1975, much of it figurative painting, that reached auction within a few years of being made. Between about 2018 and 2022 names such as Amoako Boafo, Jadé Fadojutimi, Flora Yukhnovich, Avery Singer, Salman Toor and Anna Weyant were bid far above estimate in London, New York and Hong Kong, often soon after their first gallery shows.',why:'The boom brought new, younger and Asian buyers into evening sales and made ’flipping’, the quick resale of primary-market purchases at auction, a central concern for galleries. It also widened representation, with women and artists of African descent prominent among the leading names.',look:'Look for large, saturated figurative canvases, flattened interiors and portraits, often of Black subjects, Rococo-inspired abstraction (Yukhnovich) and digitally planned painting (Singer), and check the auction trail: estimates, guarantees and how often works are resold.',artists:['Jadé Fadojutimi','Flora Yukhnovich','Avery Singer','Amoako Boafo','Salman Toor','Anna Weyant','Lucy Bull'],works:[{t:'The Lemon Bathing Suit',a:'Amoako Boafo',y:'2019',where:'private collection'},{t:'Falling Woman',a:'Anna Weyant',y:'2020',where:'private collection'},{t:'Jesture',a:'Jadé Fadojutimi',y:'2019',where:'Tate, London'}],market:{state:'cooling',note:'The category has corrected hard since 2022: ArtTactic data showed 2023 auction sales down 88% for Flora Yukhnovich, 72% for Njideka Akunyili Crosby and 68% for Salman Toor, and sales of post-2000 works by artists under 45 fell a further 49% in 2024 (Hiscox Artist Top 100). In New York, auction sales of Young Contemporary artists (born from 1980) fell another 40% in 2025 to $32.1m (Bank of America and ArtTactic), and buyers have moved back to established names.'},links:['africanmodern','neoexpressionism','digital'],sources:[['The Art Newspaper: Ultra-contemporary artists fall out of favour (2024)','https://theartnewspaper.com/2024/10/10/out-with-the-new-in-with-the-old-as-ultra-contemporary-artists-fall-out-of-favour-galleries-are-returning-to-established-names'],['Bank of America and ArtTactic: 2026 US Art Market Report','https://mlaem.fs.ml.com/content/dam/ust/articles/pdf/US-Art-Market-Report.pdf'],['ArtDependence: Hiscox Artist Top 100, 2025','https://artdependence.com/articles/according-to-the-2025-hiscox-artist-top-100-hat-100-the-sector-for-post-2000-artworks-has-slowed'],['ARTnews: New York sales underperform (May 2025)','https://www.artnews.com/art-news/news/new-york-sales-underperform-may-2025-1234743221/']],vf:'V'},
{id:'superflat',n:'Superflat and Japanese contemporary art',from:1990,to:null,place:'Tokyo and New York',what:'Superflat was named by Takashi Murakami in a 2000 exhibition in Tokyo, which travelled to Los Angeles in 2001, to describe a flattened Japanese visual culture linking Edo-period painting and ukiyo-e to anime, manga and otaku consumerism. It sits within a wider Japanese contemporary market led by Murakami, Yoshitomo Nara, whose wide-eyed children mix punk and childhood, and Yayoi Kusama, whose polka dots, Infinity Nets and mirror rooms date back to her New York years of 1958–73.',why:'Superflat erased the line between fine art and commercial production, with Murakami’s Kaikai Kiki studio making paintings, merchandise and brand collaborations such as Louis Vuitton (2003–15). It gave Japanese pop culture a place in museums and made Kusama, Nara and Murakami among the most widely collected artists in Asia.',look:'Look for flat, saturated colour and crisp outlines, cartoon characters such as Mr DOB and smiling flowers (Murakami), defiant big-headed children (Nara), and repeated dots and nets (Kusama).',artists:['Yayoi Kusama','Yoshitomo Nara','Takashi Murakami','Mr.','Aya Takano','Chiho Aoshima','Tomoo Gokita'],works:[{t:'Knife Behind Back',a:'Yoshitomo Nara',y:'2000',where:'private collection'},{t:'Infinity Mirrored Room – The Souls of Millions of Light Years Away',a:'Yayoi Kusama',y:'2013',where:'The Broad, Los Angeles'},{t:'727',a:'Takashi Murakami',y:'1996',where:'Museum of Modern Art, New York'}],market:{state:'steady',note:'Kusama was the top-selling artist for post-2000 works at auction in 2024 with $59m, down 27% on 2023 (Hiscox Artist Top 100), her record is $10.5m for Untitled (Nets) (1959) at Phillips New York in May 2022, and she died in Tokyo on 14 August 2026 aged 97. Nara holds the group’s top price, HK$196m ($24.9m) for Knife Behind Back at Sotheby’s Hong Kong in October 2019, and demand comes mainly from Asian buyers in Hong Kong, Tokyo and Seoul as well as New York.',record:'Yoshitomo Nara, Knife Behind Back (2000): $24.9m, Sotheby’s, Hong Kong, 2019',recordSrc:'https://www.sothebys.com/en/articles/sothebys-hong-kong-2019-autumn-auctions-show-resilience-with-us426-million-sales?locale=en'},links:['ukiyoe','pop','gutai','chinesecontemporary'],sources:[['Tate: Superflat','https://www.tate.org.uk/art/art-terms/s/superflat'],['Sotheby’s: Hong Kong autumn 2019 results','https://www.sothebys.com/en/articles/sothebys-hong-kong-2019-autumn-auctions-show-resilience-with-us426-million-sales?locale=en'],['Artprice: Kusama dies at 97 (2026)','https://news.artprice.com/zh/16274/yayoi-kusama-dies-at-97-the-passing-of-a-global-icon-of-contemporary-art'],['ArtDependence: Hiscox Artist Top 100, 2025','https://artdependence.com/articles/according-to-the-2025-hiscox-artist-top-100-hat-100-the-sector-for-post-2000-artworks-has-slowed']],vf:'V'}
];
